const trading=['CFA Institute RPC：The New Demands of Optimal Execution','https://rpc.cfainstitute.org/blogs/enterprising-investor/2026/new-demands-optimal-execution-machine-learning'];
export const equityLectures=[
{number:1,lead:'株式は会社の所有持分を表す。普通株・優先株の権利と、株主が最後に受け取る仕組みを確認する。',goal:'株式の種類、株主権、有限責任と残余請求権を説明できる。',sections:[
S('株を持つことは何を持つことか','株主が持つのは会社の株式であって、会社の建物や現金を直接好きに使う権利ではありません。会社は別の法人で、株式はその持分と権利を表します。会社の借入を株主個人が自動的に返すわけではなく、原則として責任は出資範囲に限られます。',[['法人','会社が契約・資産を保有','株主とは別'],['株式','会社に対する持分・権利','資産の直接所有と区別'],['有限責任','出資範囲が原則','個人保証等は別契約']],'出資を失う可能性はあり、元本保証ではありません。株価が変わるのは将来の株主CFやリスクに対する期待が変わるからです。会社が良い商品を売ることと、どの価格で株式を買うべきかは別なので、権利の地図を理解してから評価へ進みます。'),
S('普通株と優先株は条件が違う','普通株は一般に議決権や残余の利益への権利を持ち、優先株等は配当や残余財産の優先順位を契約・定款で変えます。優先という名前だけで安全とは決まりません。累積か非累積、転換・償還・議決権などの条件が価値に影響します。',[['普通株','通常の残余権・議決権','配当は自動確定ではない'],['優先株','配当・清算等に優先条件','内容は銘柄ごとに違う'],['転換権等','他の証券へ変換できる条件','追加の選択権・希薄化']],'負債は契約上の支払請求権を持ち、株主はその後の残余を得ます。ただし優先順位や保証は法域・契約で違うので、単純な三分類を実際の回収順位と決めつけないでください。会社法上の種類株式の条件を確認することが基本です。'),
S('清算の残余を計算する','架空会社の清算可能資産300万円、優先する債務220万円、優先株への清算請求50万円なら普通株主残余は30万円です。資産240なら債務後20しかなく、優先株は全額回収できず普通株は0。この例は費用・他の優先債務を省いた簡略計算です。',[['資産300','300−220−50＝30','普通株の残余'],['資産240','債務後20','優先株も請求50を満たせない'],['普通株回収','max（残余,0）','原則として負の請求にはならない']],'帳簿資産300が実際に300で売れるとは限りません。清算費用、税、担保、労働債権等も回収を変えます。PBRが低い会社を簿価そのままの清算で割安と断定しないよう、この残余構造と資産の回収可能性を一緒に見ます。'),
S('議決権比率と株数比率を分ける','発行1,000株のうち自己株式100、議決権を持つ普通株900、保有180なら、発行数比率18％でも議決権比率20％です。一株一議決権・単元制等なしの架空条件です。実務では種類株式、単元、相互保有なども確認します。',[['発行数','1,000','自己株式も含む'],['議決権総数','900','本例の自己株式を除く'],['保有180','180÷900＝20％','議決権比率']],'支配権の判断には出席率、契約、他の株主構成なども影響します。持分比率だけで役員を自由に選べると断定しません。経済的権利と意思決定権を分けて、配当や清算の価値とガバナンスへの影響を整理できればこの講義のゴールです。')],questions:[Q('普通株残余','清算資産300、債務220、優先株清算請求50（万円）。他費用なし。普通株残余＝max（資産−債務−優先株,0）。','普通株の回収は？','30万円。'),Q('資産不足','清算資産240、債務220、優先株請求50（万円）。普通株残余＝max（240−220−50,0）。','普通株回収は？','0万円。優先株も20万円しか回収できません。'),Q('議決権','発行1,000、自己株式100、保有180。残りは一株一議決権、他制限なし。比率＝180÷（1,000−100）。','議決権比率は？','20％。')],sources:[law,jpx]},
{number:2,lead:'新株を発行する市場と、既存株を売買する市場はお金の行き先が違う。参加者の役割を整理する。',goal:'発行市場・流通市場・仲介者・機関投資家を資金の流れで説明できる。',sections:[
S('会社へお金が入るのは発行市場','発行市場では会社が新株等を発行し投資家から資金を得ます。架空会社が一株1,000円で10万株を新規発行すると総額1億円です。発行費用が200万円なら手取9,800万円。調達総額、会社手取、時価総額は同じ数字ではありません。',[['発行会社','新株10万株を出す','資金を受け取る'],['投資家','1,000円×10万株を払う','新しい持分を得る'],['手取','1億−200万＝9,800万','費用を差し引く']],'IPOには新株発行だけでなく既存株主による売出しもあります。売出し代金は通常既存株主へ入り、会社の設備投資資金が同額増えるわけではありません。募集と売出しを分け、資金使途と株主構成を目論見書等で確認します。'),
S('流通市場では保有者が入れ替わる','上場後の通常売買は投資家から投資家へ株式を移します。Aが1,200円で100株をBへ売れば、Bが12万円を払いAが受け取ります。会社へ直接12万円が入るのではありません。ただし流動性と市場価格は将来の発行条件や資本コストへ影響します。',[['買い手B','12万円を支払う','既存株100株を得る'],['売り手A','12万円を受け取る','保有を手放す'],['会社','直接の資金入金なし','市場評価の情報は得る']],'株価上昇で会社の現金が自動で増えるわけではありません。新株発行、株式対価買収、従業員報酬などには影響します。発行市場と流通市場の区別は、株価が会社経営へどう伝わるかを考える出発点になります。'),
S('市場参加者は目的が違う','個人、年金、投信、保険、ヘッジファンドなどは投資期間や制約が違います。証券会社は売買の仲介や引受、取引所は取引の場とルール、清算機関は決済のリスク管理を担います。誰もが同じ情報と時間軸で売買するわけではありません。',[['長期資金','年金・保険等','負債や運用制約がある'],['仲介・引受','証券会社等','手数料・利益相反を確認'],['市場基盤','取引所・清算機関','価格発見・履行の仕組み']],'市場が多様な参加者で成り立つことと、すべての取引が情報に基づくことは別です。指数連動、資金流出、担保不足などによる売買もあります。株価の一日の動きに一つのニュースだけを理由として当てはめず、売買需要と事業期待を区別します。'),
S('流動性は会社の資金調達にも効く','流動性が高いとは、比較的小さい価格影響と費用で売買できることです。出来高が大きくてもストレス時に板が薄くなる場合があります。投資家は売りにくさへの補償を求めるため、流動性は必要収益率や発行価格に影響し得ます。',[['価格発見','売買で市場評価が形成','常に正しい価格とは限らない'],['流動性','スプレッド・板・出来高','大量注文の影響も確認'],['調達との関係','売りやすさが要求率へ影響','直接の会社入金と区別']],'通常売買で会社に入金がないから流通市場は不要、という結論にはなりません。退出できる市場があるから発行時に資金を出しやすい面があります。資金の行き先と、間接的な価格・流動性の機能を別々の矢印で説明しましょう。')],questions:[Q('手取','新株10万株、価格1,000円、発行費用200万円。手取＝株数×価格−費用。','会社手取は？','9,800万円。'),Q('通常売買','既存株100株をAがBへ一株1,200円で売却。費用なし。通常の投資家間取引で会社への払込なし。','12万円は誰へ入る？','売り手A。会社へ直接入りません。'),Q('売出し','IPOで既存株主が保有株を売り出し総額1億円。新株発行なし、費用なし。代金は売却保有者へ入る。','会社が1億円を調達した？','いいえ。既存株主の売却代金です。')],sources:[jpx,fiea]},
{number:3,lead:'TOPIXと日経平均は、同じ日本株でも重みが違う。指数の上昇を個々の企業の上昇と取り違えない。',goal:'時価加重と株価加重を区別し、配当・通貨・構成の比較条件を説明できる。',sections:[
S('指数は市場をまとめる物差し','株価指数は複数銘柄の動きを決まった方法でまとめます。TOPIXは浮動株調整時価総額加重、日経平均は225銘柄の株価平均型の指数です。採用基準、調整、構成変更などはそれぞれの公式ルールに従うため、単なる全社平均とは言えません。',[['TOPIX','浮動株調整時価加重','売買可能持分を調整'],['日経平均','225銘柄・株価平均型','株価換算係数等で調整'],['海外指数','S&P500等','対象・通貨・算式を確認']],'制度は改定されるため、対象銘柄数や構成を永久に固定して説明しません。本講義の計算は公式指数の実数ではなく、二銘柄の簡略モデルです。公式の算式・構成と、重みの違いを学ぶための架空例を分けて見てください。'),
S('時価加重の簡略例','Aの時価80億円・B20億円なら重み80％・20％。Aが10％上昇、Bが変化なし、株数や構成が不変なら指数リターン8％です。浮動株調整を行う公式指数では、会社全体の時価ではなく調整後の時価などを使います。',[['A','重み80％・リターン10％','寄与8ポイント'],['B','重み20％・リターン0％','寄与0'],['指数','0.8×10＋0.2×0＝8％','簡略時価加重']],'大企業の動きが全体を強く左右します。指数が上がっても小型株や多くの業種が下がることはあり得ます。値上がり銘柄数、業種寄与、集中度も確認し、指数一つを景気や全企業の業績と同一視しないようにします。'),
S('株価加重では高株価の影響が大きい','単純な株価加重モデルでA株価1,000円・B100円なら重みは約90.91％・9.09％です。Aが10％上昇すると指数は約9.09％上昇。会社の規模が小さくても一株価格が高いと影響が大きくなる点が、時価加重と違います。',[['A','1,000÷1,100≈90.91％','株価による重み'],['B','100÷1,100≈9.09％','発行株数はここで使わない'],['Aだけ10％上昇','指数約9.09％','公式日経の実計算ではない']],'株式分割だけで経済価値は変わらないので、公式指数は除数や換算係数等を調整します。「日経平均は225社の株価を足して225で割るだけ」と説明すると、こうした調整を見落とします。算式の狙いと実装の違いを区別します。'),
S('比較するなら配当と通貨をそろえる','価格指数は配当を直接含まないのに対し、配当込み指数は再投資等を反映します。日本円の指数と米ドル指数の騰落をそのまま比べると為替を無視します。指数連動商品も信託報酬や取引費用があり、指数リターンと完全一致しません。',[['価格指数','株価変化中心','配当込みとは違う'],['配当込み','配当再投資等を反映','税引前後も確認'],['外貨投資','（1＋外貨収益）×（1＋為替収益）−1','円評価へ変換']],'米ドルで株価5％上昇、円から見てドル10％上昇なら円リターン15.5％です。期間、配当、通貨、対象の四条件をそろえて指数を比較します。構成ルールが異なるので、二つの指数の差がそのまま運用者の能力差になるわけでもありません。')],questions:[Q('時価加重','A時価80・B20、A収益10％・B0％。株数不変、指数収益＝時価重み×収益の和。','指数収益は？','8％。'),Q('株価加重','簡略株価加重：A1,000円・B100円、A10％上昇・B不変。A重み＝1,000÷1,100、指数収益＝A重み×10％。','指数収益は？','約9.09％。'),Q('円リターン','外貨株の収益5％、円で測った外貨の上昇10％。円収益＝1.05×1.10−1。費用・税なし。','円収益は？','15.5％。')],sources:[topix,nikkei]},
{number:4,lead:'約定したら終わりではない。現物・信用取引と、清算・受渡までの資金と証券の流れを確認する。',goal:'日本のT＋2と信用取引の増幅・費用・追証の基本構造を説明できる。',sections:[
S('現物は資金と株式を交換する','現物買いは株式を買付代金で取得します。一株1,000円で100株なら10万円、手数料等は別。約定は売買が成立したことで、受渡は資金と株式の移転を履行することです。画面の約定通知と、決済が完了した状態を分けます。',[['注文','条件を証券会社へ出す','未成立の段階'],['約定','相手注文と売買成立','価格・数量が決まる'],['受渡','資金と証券の履行','清算・決済を経る']],'株を売った日に売却代金を無条件で出金できるとは限らず、証券会社の取扱いも確認します。株主権の基準日や権利落ちとも関係するため、カレンダー上の日数ではなく取引日・決済日を意識することが大切です。'),
S('日本株の通常決済はT＋2','日本の対象株式等の通常決済は約定日から二営業日後、T＋2です。祝日なしで月曜約定なら水曜受渡。金曜約定なら翌火曜となります。海外市場は別制度で、米国等のT＋1を日本の説明へ混ぜないでください。',[['月曜約定','火曜T＋1・水曜T＋2','祝日なし'],['金曜約定','月曜T＋1・火曜T＋2','土日は営業日外'],['例外・変更','市場・商品ごとに確認','最新の公式案内に従う']],'清算機関は債務引受け等を通じ履行のリスクを管理しますが、市場リスクが消えるわけではありません。決済期間、証券保管、証券会社の預り区分は別の役割です。学習の計算では営業日の条件を明示し、休日を飛ばして数えます。'),
S('信用取引は借入で持分を増幅する','信用買いは資金を借り、信用売りは株式を借りる仕組みです。自己資金30万円で100万円の株式を持つ架空例では、株価10％下落で損失10万円、自己資金比率では約33.33％。実際の委託保証金基準や規制は証券会社・制度で確認します。',[['建玉','100万円','市場のリスク対象額'],['自己資金','30万円','保証金の簡略例'],['株価10％下落','損失10万・自己資金20万','元本比約33.33％減']],'この30％は簡略演習の入力で、現在の一律保証金基準の案内ではありません。金利、貸株料、逆日歩等の費用、期限、追加保証金が利益を変えます。空売りは理論上の損失上限がなく、元本を超える損失が生じ得る点にも注意します。'),
S('借りた証券・資金には条件がある','制度信用と一般信用は対象・期限・費用等の条件が異なります。追証の判定、強制決済、配当相当額、株主権の取扱いも現物と違います。株価が戻るまで無期限に持てると考えず、契約と資金繰りを先に確認します。',[['信用買い','借入利息等','保有コストが発生'],['信用売り','貸株・逆日歩等','調達不能や費用増のリスク'],['管理','保証金・期限・返済','価格予測だけでは足りない']],'信用取引のリスクは価格だけでなく、資金調達と証券調達のリスクです。利益を見積もる際は売買差額から保有費用と手数料を引きます。この講義は仕組みを学ぶもので利用を推奨するものではなく、実際の条件は取引所と証券会社の最新情報へ進んでください。')],questions:[Q('受渡日','日本株通常T＋2、営業日は月〜金、祝日なし。金曜に約定。約定日をTとして二営業日後に受渡。','受渡はいつ？','翌火曜です。'),Q('信用の増幅','自己資金30万円、借入70万円で建玉100万円。株価10％下落、費用なし。損失＝建玉×10％。','損失と自己資金比率は？','10万円、約33.33％です。'),Q('保有費用','信用買いの売買差益2万円、利息等3,000円、手数料1,000円。純益＝差益−費用。','純益は？','16,000円。')],sources:[settlement,jpx]},
{number:5,lead:'成行は価格を保証せず、指値は約定を保証しない。注文板から価格優先・時間優先を考える。',goal:'成行・指値の売買結果と、注文駆動・気配駆動の違いを説明できる。',sections:[
S('買い指値は上限、売り指値は下限','買い指値1,000円は1,000円以下なら買う条件、売り指値1,000円は1,000円以上なら売る条件です。成行は価格を指定しないので、板が薄いと複数の価格で約定します。最終取引値で希望数量をすべて買える保証はありません。',[['買い指値','上限1,000円','それより高く買わない'],['売り指値','下限1,000円','それより安く売らない'],['成行','価格を指定しない','価格・全部約定の保証なし']],'指値でも板や時間条件によって一部しか約定しない、全く約定しない場合があります。成行でも特別気配や取引停止等で即時約定しないことがあります。「価格と数量のどちらを優先するか」を意識して注文条件を選ぶ仕組みです。'),
S('板を食べると平均価格が上がる','架空の売り板は1,000円に100株、1,010円に200株。成行買い200株なら、100株ずつ二段で約定し平均1,005円、代金201,000円。最良売り気配1,000円だけで200株を掛けると、数量による価格影響を見落とします。',[['第1段','1,000円×100株＝100,000','先に約定'],['第2段','1,010円×100株＝101,000','次の価格へ'],['平均','201,000÷200＝1,005円','手数料なし']],'板は注文の取り消しや新規注文で変わります。この図は一瞬の固定板に対する演習で、実際の注文結果を保証しません。大量買付では市場インパクトや情報漏れが費用になります。取引前の気配と実際の平均約定価格を別々に記録します。'),
S('価格優先と時間優先','連続取引の基本では買いは高い価格、売りは低い価格が優先。同価格なら先に出た注文が優先されます。市場開始・終了等の板寄せは連続取引とルールが違うため、時間優先を全場面へ機械的に適用しないでください。',[['買い注文','1,010円が1,000円より先','価格優先'],['売り注文','1,000円が1,010円より先','低い価格が優先'],['同じ価格','原則先に出した注文','ザラバの基本・例外は公式確認']],'東証の板寄せ・ザラバ・特別気配等の制度は公式案内で確認します。価格上限や売買停止もあるので、オーダーブックの単純モデルだけで実際の約定を断言しないことが重要です。どの取引方式を想定した問題なのかを先に明示します。'),
S('注文駆動と気配駆動','注文駆動市場は買い手と売り手の注文を合わせます。気配駆動市場はディーラーが提示する売買価格で取引する構造です。現実には混合方式もあります。最良買い990・売り1,000なら提示スプレッド10円、中値995円です。',[['注文駆動','参加者の注文板','価格・時間で組み合わせ'],['気配駆動','ディーラーの売買提示','在庫・信用・収益を反映'],['スプレッド','1,000−990＝10円','中値との差は片側5円']],'スプレッドは流動性の費用の入口ですが、実際の費用は注文量、時間、手数料、市場変動で変わります。中値と気配、約定値の三つを分けると、売買方式と取引コストの関係が見えます。指値が安いというだけで機会損失を無視しないようにします。')],questions:[Q('成行の平均','固定売り板：1,000円100株、1,010円200株。成行買い200株、費用なし。安い売り板から約定し平均＝代金÷株数。','平均約定値は？','1,005円。'),Q('買い指値','売り板は1,000円100株、1,010円200株。買い指値1,000円で200株。板変化なし、上限以下だけ約定。','何株買える？','100株。残100株はこの条件では未約定です。'),Q('提示スプレッド','最良買い990円・売り1,000円。スプレッド＝売り−買い、中値＝（売り＋買い）/2。','スプレッドと中値は？','10円、995円。')],sources:[jpx]},
{number:6,lead:'景気から業種を選ぶか、会社から調べるか。どちらも事業の売上・費用・資本へつなげる。',goal:'トップダウンとボトムアップを区別し、産業の感応度を予測へ反映できる。',sections:[
S('二つの分析方向を往復する','トップダウンは経済、業種、会社へと下り、ボトムアップは会社の製品、顧客、財務から価値を考えます。どちらも万能ではありません。景気予測が正しくても株価に織り込み済みなら儲かるとは限らず、優良会社も業界構造で利益を失うことがあります。',[['トップダウン','景気→業種→会社','共通環境から選ぶ'],['ボトムアップ','会社→業界→環境','固有の強みから検証'],['往復','仮説と企業データを照合','片方だけで完了しない']],'株式分析では事業の良さと市場価格を分けます。成長市場という言葉だけで高いマルチプルを正当化せず、価格競争、必要投資、既存の期待を確認します。分析の順序を決めることと、結論を先に固定することは違うと意識してください。'),
S('需要を数量と単価に分ける','架空の設備会社の販売量100台・単価100万円なら売上1億円。景気回復で数量10％増、価格5％下落なら売上1.045億円、4.5％増です。数量と単価の変化率を単純に足した5％とは違います。事業モデルで価格転嫁力を考えます。',[['基準','100台×100万円＝1億','数量と単価'],['予測','110台×95万円＝1.045億','競争で単価下落'],['売上成長','1.10×0.95−1＝4.5％','掛算の効果']],'市場全体の伸びと自社のシェア変化も分けます。市場が10％伸びても自社シェアが減れば成長は弱くなります。新規参入、代替技術、顧客集中、地域ごとの需要を確認し、産業平均をすべての会社へ同じように適用しないでください。'),
S('環境変化を費用と資本へ写す','原料高、為替、金利、賃金は業種と契約で効き方が違います。架空の輸入小売では円安が仕入を押し上げますが、輸出企業では外貨売上が増える場合があります。価格転嫁、ヘッジ、海外生産、借入の通貨を確認して純影響を考えます。',[['原料価格','変動原価へ影響','販売価格転嫁の時間差'],['需要増','在庫・売掛金が増える','売上とCFの差'],['金利上昇','借入・顧客需要へ影響','固定金利と変動を分ける']],'利益の方向だけでなくタイミングが重要です。価格転嫁が半年遅れれば短期利益とCFが落ちる可能性があります。営業利益の予測を作ったあと、設備投資と運転資本へつなげ、成長による資金拘束がないかも検討します。'),
S('仮説は確認資料へつなげる','政府・業界の統計、会社の決算、セグメント、顧客、価格、受注などで仮説を検証します。単月の数量や一社の説明を産業全体の確定事実としません。期間、地域、商品範囲をそろえ、事実と推計と意見を区別して残します。',[['事実','公表済み統計・決算','出所と期間を記録'],['推計','将来需要・シェア','条件と幅を示す'],['反証','受注減・採算悪化等','どの数字なら見方を変えるか']],'分析を更新する条件を先に決めると、都合の良いニュースだけを集める偏りを抑えられます。上振れと下振れを同じPL・CF項目で作り、投資判断は価格を加えて検討します。産業分析は株価予測の断言ではなく、企業価値の前提を作る作業です。')],questions:[Q('売上予測','基準販売100台・単価100万円。数量10％増、単価5％減。新売上＝100×1.10×100万円×0.95。','売上と成長率は？','1億450万円、4.5％増。'),Q('分析の順序','景気→業種→会社をトップダウン、会社の製品・財務→業界をボトムアップと定義。','会社の顧客継続率から調べる方法は？','ボトムアップです。外部環境の検証も必要です。'),Q('資金拘束','成長で売掛金20・在庫10増、買掛金5増（百万円）。NWC増＝債権増＋在庫増−債務増、FCF影響は逆符号。','FCFへの影響は？','−25百万円。')],sources:[forecast,nyu]},
{number:7,lead:'成長期・成熟期で競争と投資の条件は違う。競争優位が続く理由を、利益率と資本へ落とす。',goal:'産業ライフサイクルと競争優位を、将来ROICと再投資の仮説へつなげられる。',sections:[
S('ライフサイクルは分析の型','導入、成長、成熟、衰退という分類は、需要、競争、投資の変化を整理する型です。すべての産業が同じ順序・期間をたどるわけではありません。再成長、技術の交代、地域差があるため、「成熟だから投資不要」と機械的に判断しないでください。',[['導入・成長','需要拡大と先行投資','赤字CFでも将来採算を検証'],['成熟','価格競争・更新需要','維持投資と効率を重視'],['衰退','数量減・退出・再編','資産回収と撤退費用を確認']],'売上成長が鈍っても利益とCFが良くなる場合があります。反対に高成長でも顧客獲得費や設備資金がかさみ価値を減らす場合があります。会社のステージだけで投資の結論を出さず、将来の増分収益率と価格を合わせて見ます。'),
S('競争優位はなぜ模倣できないか','ブランド、規模、ネットワーク、切替費用、特許、低コスト資源などは競争優位の候補です。名称を挙げるだけでは証明になりません。顧客の継続、価格差、単位原価、投下資本利益率が競争下で維持できる理由を説明します。',[['切替費用','移行に時間・費用がかかる','顧客継続へ影響'],['規模の経済','固定費を広く分担','需要・稼働率が条件'],['ネットワーク','利用者が他の利用者価値を高める','競合・マルチ利用も確認']],'一時的な供給不足による高利益率を恒久的な優位としません。高ROICは参入を誘うため、保護要因がなければ競争で下がりやすくなります。数字が良い理由と、将来も続く理由を二段階で検証することが重要です。'),
S('利益率だけでなく資本回転を見る','架空企業AはNOPAT利益率15％・売上/資本2倍、Bは利益率20％・回転0.5倍。ROICはA30％、B10％。高マージンだけで優位を比較すると、必要設備や運転資本を見落とします。会計調整の定義が同じという条件で比べます。',[['A','15％×2＝30％','資本が軽いモデル'],['B','20％×0.5＝10％','大きな設備負担'],['比較','利益率×資本回転＝ROIC','同じNOPAT・資本の定義']],'業種が異なるなら、単純にAが優良と決めないでください。リスク、更新投資、成長、規制、必要収益率も違います。優位を評価へ移すときは、いつ競争が強まり、どの程度ROICが正常化するかをシナリオにします。'),
S('優位の持続期間を評価に反映する','DCFや残余利益モデルでは、超過利益が何年続くかが価値に効きます。永遠に高成長・高ROICを維持すると巨大な価値になりやすいので、研究開発、競合参入、規制、顧客行動を検証します。優位維持の費用もCFに含めます。',[['短期','受注・数量・価格を予測','具体的な根拠を使う'],['移行期','利益率・ROICの変化','競争による収束を検討'],['安定期','成熟した成長と投資','維持支出はゼロにしない']],'「強い会社」でも株価に十分な期待が入っていれば割安ではありません。競争優位、必要再投資、持続年数、割引率、価格を順に置きます。評価結果を一つの数字にせず、優位が早く失われた場合の価値も確認して説明しましょう。')],questions:[Q('ROIC分解','AはNOPAT利益率15％・資本回転2倍。ROIC＝利益率×回転。定義・期間は整合。','ROICは？','30％。'),Q('高マージン','B利益率20％・資本回転0.5倍。ROIC＝利益率×回転。','ROICは？','10％。利益率だけでは資本効率を比較できません。'),Q('維持コスト','売上100、現金費用70、優位維持に必要な追加支出5（百万円）。税・他投資なし、FCF＝売上−全現金支出。','FCFは？','25百万円。維持支出5を無視した30ではありません。')],sources:[forecast,nyu]},
{number:8,lead:'ESG情報を点数で終わらせない。環境・人材・統治が売上・費用・資本・リスクへどう効くかを見る。',goal:'非財務情報の重要性を事業モデルと結び付け、対話の目的を説明できる。',sections:[
S('重要性は業種と事業で違う','ESGは環境、社会、ガバナンスに関する情報です。企業価値分析では、それが将来CFや資本コストにどのような経路で影響するかを考えます。排出量、労働安全、顧客保護、利益相反などの重要性は事業ごとに異なります。点数の高低だけで投資結論を出しません。',[['環境E','燃料・排出・資源・災害','費用・需要・資産への経路'],['社会S','安全・人材・顧客・供給網','継続性と費用に影響'],['統治G','監督・報酬・株主権','資本配分と利益相反']],'持続可能性への社会的影響と、会社への財務的影響は関連しても同じ概念ではありません。どの視点で重要性を判断するかを明示します。企業の宣言を実績と取り違えず、対象範囲、期間、測定方法、比較可能性を確認しましょう。'),
S('非財務の変化をCFへ変換する','架空工場の排出10万トン、追加負担の仮定単価1,000円/トンなら費用1億円。削減設備5億円で年間費用を0.8億円節約できても、維持費0.1億円なら純節約0.7億円です。これは制度実額ではなく感応度を学ぶ仮定です。',[['追加負担','10万×1,000＝1億','税・制度実額ではない'],['削減便益','年0.8億','削減量・価格の仮定'],['純便益','0.8−0.1＝0.7億','投資5億を別評価']],'費用だけでなく補助金、税、設備寿命、規制、商品需要も変わります。NPVでは年数と割引率を指定し、削減費用を無限に続けないでください。割引率へ同じリスクをさらに加算すると二重反映になることがあるので、CFと割引率を分けて記録します。'),
S('指標の境界と検証を見る','排出量ならScopeや連結範囲、労働指標なら正社員だけか委託先も含むか、ガバナンスなら制度と運用を確認します。買収で範囲が広がれば数値が増えても効率が悪化したとは限りません。総量と原単位を両方見ることが大切です。',[['総量','排出100→110','活動規模の影響を含む'],['売上','100→125','同じ単位の架空例'],['原単位','1→0.88','総量増でも効率改善']],'原単位が下がっても総量の目標を達成したとは言えません。外部保証の範囲、データ欠測、算定変更、過去修正を確認します。ランキングや企業の図だけで結論を出さず、財務データと同様に定義と範囲をそろえて比較してください。'),
S('エンゲージメントは改善の対話','投資家のエンゲージメントは経営との対話を通じ、重要課題への理解や行動改善を促す活動です。議決権行使、期限付き目標、フォローアップを組み合わせます。対話した回数が多いだけで企業価値改善を証明するわけではありません。',[['課題','重要なリスク・機会を特定','会社固有の根拠を持つ'],['対話','方針・責任・期限を確認','一方的要求だけにしない'],['評価','実績と行動を継続確認','成果と市場要因を分ける']],'良い対話は、資金用途、事業リスク、情報の不足を具体的に扱います。重要な未公表情報を受け取る可能性がある場合は、法令・社内管理を守る必要があります。ESGを飾りではなく、将来CFの前提とガバナンスの検証へつなげることを学びます。')],questions:[Q('排出費用の仮定','排出10万トン、計算用負担単価1,000円/トン。費用＝数量×単価。現行税額ではない。','費用はいくら？','1億円。'),Q('純節約','削減設備の年節約0.8億円、追加維持費0.1億円。税等なし、純便益＝節約−維持。','年純便益は？','0.7億円。'),Q('原単位','排出量100→110、売上100→125。原単位＝排出÷売上。同じ算定範囲。','原単位の変化は？','1から0.88へ12％低下。ただし総排出は10％増えています。')],sources:[gov,forecast]},
{number:9,lead:'一株の値段、株主全体の値段、事業の値段は違う。EVから株式価値への橋を自分で作る。',goal:'時価総額と簡略EVを計算し、現金・負債・非支配持分の調整を説明できる。',sections:[
S('株価は一株、時価総額は全体','架空会社の株価1,000円、自己株式等調整後の対象株数1億株なら株式時価総額1,000億円です。一株価格が低い会社が小さいとは限りません。株式分割で一株価格が下がっても、株数が増えるので全体価値はそれだけでは変わりません。',[['一株価格','1,000円','小口の価格'],['対象株数','1億株','自己株式・潜在株の定義を確認'],['時価総額','1,000×1億＝1,000億','株主全体の市場価格']],'ウェブ表示の時価総額は株数定義が異なる場合があります。評価モデルでは希薄化後株数や自己株式をどう扱うか明示します。株価比較は円の大小ではなく、一株が何の利益・CF・資産への持分かを確認して行います。'),
S('EVは事業側への橋','簡略EV＝株式時価総額＋有利子負債−現金。株式1,000億円、負債400、現金100ならEV1,300です。本講義では現金を全額事業外とする仮定。実務は優先株・非支配持分・リース・運営必要現金・他の事業外資産などを確認します。',[['株式時価','1,000','株主の価値'],['負債・現金','＋400−100','資金構成の調整'],['簡略EV','1,300億円','事業側の比較値']],'EVの定義はデータ提供者でも違うため、比較企業でそろえます。連結EBITDAを使うなら非支配持分の対応を検討し、リースを負債に含めるなら利益指標の調整も一致させます。数字を引くだけで万能な企業価値になるわけではありません。'),
S('DCF事業価値から株式価値へ','DCFで得た事業価値1,500億円に事業外現金100を足し、負債400を引くなら株式価値1,200。一億株なら一株1,200円です。市場のEV1,300とモデル事業価値1,500を比較することと、株価1,000とモデル一株1,200を比較することは対応します。',[['モデル事業価値','1,500','FCFFをWACCで評価'],['株式価値','1,500＋100−400＝1,200','その他調整なし'],['一株価値','1,200億÷1億＝1,200円','株数の単位を合わせる']],'予測が正しい場合のモデル値であり、必ず1,200円になるという話ではありません。負債を簿価で近似する理由、現金の範囲、優先請求を確認します。FCFEで直接株式価値を求めたのに、負債をもう一度引くのは二重調整です。'),
S('分割と資金移動を区別する','一対二の株式分割なら株数一億から二億、一株価格1,000から500、全体価値1,000億円は不変という簡略例です。新株発行は資金が入り、買付は現金が出るため分割とは違います。株数の変化の原因を先に確認します。',[['分割','価格半分・株数二倍','資金入出なし'],['新株発行','株数と会社資金が増える','投資用途と発行価格を評価'],['買付','現金と対象株数が減る','取得価格と定義を確認']],'一株価値を使うときは評価日と株数基準をそろえます。古い決算EPSへ分割後株価を当てると比率がゆがみます。価格、対象株数、事業価値、資金構成を一枚に描き、どの価値を比較しているか声に出して説明してください。')],questions:[Q('時価総額','株価1,000円、対象株数1億株。時価総額＝株価×株数。','時価総額は？','1,000億円。'),Q('EV','株式時価1,000、有利子負債400、現金100（億円）。本問EV＝株式＋負債−現金。その他調整なし。','EVは？','1,300億円。'),Q('一株価値','DCF事業価値1,500、事業外現金100、負債400（億円）、株数1億。株式価値＝事業＋現金−負債。','一株価値は？','1,200円。')],sources:[fcf,multiple]},
{number:10,lead:'PER・PBR・PSRなどを同じ会社で並べる。安い比率が割安の証明にならない理由まで整理する。',goal:'各マルチプルの分子・分母を一致させ、負の利益や会計差の限界を説明できる。',sections:[
S('株主側の指標を一覧で読む','架空会社の株式時価1,000億円、株主利益50、株主簿価500、売上2,000、株主側CF100と定義すると、PER20倍、PBR2倍、PSR0.5倍、PCFR10倍です。PCFRは統一された一つの定義ではなく、この講義では株式価値÷定義済み株主CFとします。',[['PER・PBR','1,000/50＝20・1,000/500＝2','利益と簿価への倍率'],['PSR','1,000/2,000＝0.5','売上に利益率を別途検討'],['PCFR','1,000/100＝10','CF定義を必ず添える']],'営業CFを使うPCFRなど別の定義もあるので、データ元と比較条件を確認します。PERの利益は親会社株主帰属など対象範囲と予想・実績をそろえます。赤字の負のPERを小さいから割安と読むことはできません。比率は評価の問いを作る入口です。'),
S('事業側のEV/EBITDA','株式1,000、負債400、現金100なら簡略EV1,300億円。EBITDA200と定義するとEV/EBITDA6.5倍。事業価値を株主利益で割ったEV/PERのような不整合を避けます。連結範囲、リース、調整EBITDA、非支配持分も対応を確認します。',[['EV','1,300','資金構成調整後'],['EBITDA','200','会社間で定義をそろえる'],['倍率','1,300/200＝6.5','設備投資・税・NWCを直接含まない']],'EBITDAが同額でも多額の維持投資が必要な会社はCFが小さくなります。低いEV/EBITDAだけで割安と決めず、資産寿命、設備更新、税、運転資本を検討します。金融機関では負債が事業の一部なので、一般事業会社のEV倍率を機械的に当てません。'),
S('低PERの理由を分解する','低PERは成長期待の低さ、利益ピーク、会計一時益、高リスクなどの結果かもしれません。AのPER10・次期利益半減なら価格不変で予想PER20。BのPER20・利益二倍なら予想PER10。基準年だけで割安順位を決めると逆転を見落とします。',[['A','現利益100・価格1,000','PER10、次期利益50なら20'],['B','現利益50・価格1,000','PER20、次期利益100なら10'],['検証','正常利益・成長・要求率','将来利益は仮定である']],'景気敏感企業はピーク利益でPERが低く見え、利益底では高く見えることがあります。PBRも資産回収力や将来ROEに依存します。PSRは低利益率会社で低くなるため、倍率の大小を根拠なしに企業の優劣へ変換しないでください。'),
S('比較表には条件を必ず付ける','同じ評価日、同じ通貨、実績か予想か、連結範囲、会計基準、調整項目をそろえます。自社株買いや分割で株数が変わる場合、EPSと株価の基準を合わせます。類似会社の中央値は参考値で、成長・リスク・資本効率差を消すものではありません。',[['期間','今期予想同士で比較','過去と将来を混ぜない'],['会計','一時益・リース・償却','調整する理由を明記'],['結論','倍率と事業の差を説明','低倍率だけで買い判断しない']],'マルチプルで出した価値をDCFや残余利益モデルと比べ、差の理由を前提から探ります。複数の指標を平均しただけで誤差が消えるわけではありません。指標名、計算式、使える条件、弱点を一緒に説明できればこの講義のゴールです。')],questions:[Q('PERとPBR','株式価値1,000、株主利益50、株主簿価500（億円）。PER＝価値/利益、PBR＝価値/簿価。','各倍率は？','PER20倍、PBR2倍。'),Q('EV倍率','本問EV1,300億円、定義済みEBITDA200億円。EV/EBITDA＝1,300/200。','倍率は？','6.5倍。'),Q('利益半減','株式価格全体1,000億円、今年利益100、次期予想利益50。価格不変、PER＝価格/対象期利益。','今年と次期PERは？','10倍と20倍。低い今年PERだけで割安とは言えません。')],sources:[multiple,fcf]},
{number:11,lead:'配当を現在へ割り引いて株式価値を求める。保有期間の最後の売却価格も、未来の配当とつながっている。',goal:'一期間DDMと永続DDMの構造、使いやすい会社と限界を説明できる。',sections:[
S('DDMは株主への配当を評価する','配当割引モデルDDMは、将来の一株配当を株主資本コストKeで割り引きます。会社全体の営業CFをWACCで割る方法とは違います。配当が利益や株主CFと結び付き、方針がある程度安定した会社で使いやすいモデルです。配当だけが企業の経済価値のすべてではありません。',[['評価CF','一株配当Dt','株主が受け取る金額'],['割引率','Ke','株主の要求収益率'],['価値','ΣDt/(1＋Ke)^t','各配当時点で割引']],'自社株買い中心、無配当、高成長の会社では、配当予測だけだと還元政策を十分に表せない場合があります。FCFEや総還元モデル、残余利益などを検討します。モデルを選ぶ理由を説明し、無配当だから会社価値ゼロと判断しないでください。'),
S('一年保有なら配当と売却価格','架空株式で一年後配当40円、一年後予想価格1,040円、Ke8％なら現在価値（40＋1,040）÷1.08＝1,000円。売却価格も株主の回収なので含めます。ただしそれは将来の市場価格予測で、確定した売却代金ではありません。',[['年1末配当','40円','株主の回収'],['年1末売却','予測1,040円','同じ時点の回収'],['現在価値','1,080÷1.08＝1,000円','両方を一回割引']],'将来株価を根拠なしに置くと評価が循環します。売却先もその後の配当やCFを評価するので、長期のDDMでは売却価格を将来配当の価値へ置き換えます。配当と価格を同じ時点へ合わせ、価格に既に含まれる配当を重複させないことが重要です。'),
S('成長しない配当の例','一年後から毎年50円の配当が永久に続き、Ke10％なら価値500円。初回が今日なら今日の配当を別に足します。毎年一定は簡略仮定で、利益、投資、分配可能額、現金余力に裏付けがなければそのまま永久配当にはできません。',[['配当D1','50円','初回一年後'],['成長g','0％','同額が続く仮定'],['価値','50÷0.10＝500円','永久年金の応用']],'この式は負債や現金をさらに引き足す前の事業価値ではなく、配当から直接求めた株式価値です。負債の効果は配当余力とKeに反映されるので、負債をもう一度引くと二重計上です。価値の受益者を式の横に書いて確認しましょう。'),
S('価格との比較は予測の検証から','モデル価値500円、市場価格450円ならモデル上の差50円。ただし配当やKeの前提が誤れば差は消えます。配当引下げ、金利上昇、事業リスクを検討し、価格が低い理由を探します。モデル価格を将来の必達株価として発信しないでください。',[['前提','利益・配当・投資を整合','配当は決定と資金に制約'],['感応度','Keや配当を変更','価値の範囲を確認'],['判断','モデルと市場期待を比較','乖離は利益保証ではない']],'配当を増やすため維持投資を削るなら、長期の配当能力が落ちる可能性があります。配当実績と予測を分け、税引前後の扱いも統一します。DDMの式は短くても、将来の配当を作る企業の事業・資本配分を分析する作業は省略できません。')],questions:[Q('一年DDM','一年後配当40円、年末予想価格1,040円、Ke8％。P0＝（D1＋P1）÷1.08。','現在価値は？','1,000円。'),Q('無成長DDM','一年後から永久に配当50円、Ke10％、成長0。価値＝D/Ke。','価値は？','500円。'),Q('価値の種類','配当をKeで割り引いて一株価値500円を得た。配当は利息等の支払後の株主回収。負債は既に反映される。','ここから一株負債を再び引く？','引きません。直接株式価値を求めたため二重調整です。')],sources:[ddm]},
{number:12,lead:'一定成長の配当を一本の式にまとめる。D0とD1、Keとgの差が価値を大きく変える。',goal:'ゴードン成長モデルを計算し、Ke＞gと安定成長の前提を説明できる。',sections:[
S('今期配当を来期へ進める','ゴードン成長モデルはP0＝D1/(Ke−g)です。架空会社の今期配当D0＝40円、永続成長g2％、Ke8％ならD1＝40.8円、価値680円。D0を直接分子へ入れた約666.67円は、受取時点が一つ違います。',[['D0','今期40円','成長前の基準'],['D1','40×1.02＝40.8円','来期末配当'],['P0','40.8÷（0.08−0.02）＝680','現在の株式価値']],'配当成長を予測するには、利益と留保・再投資を確認します。成長を続けるのに必要な資本を無視し、配当だけ増やす前提は不整合になります。式に入れる配当は評価後の初回配当で、既に権利落ち済みの受取を再度含めないようにします。'),
S('Keがgを上回る必要がある','Ke＞gのとき無限の割引配当が収束します。D1＝40.8円でKe8％・g2％なら680、g4％なら1,020。g8％では分母0で使えません。gがKeを超えて得た負の数値をマイナスの企業価値として解釈するのは誤りです。',[['Ke8・g2','分母6％・価値680','初回D1固定の感応度'],['Ke8・g4','分母4％・価値1,020','永続成長の影響大'],['Ke≦g','収束しない','モデルを変更']],'高成長期の10％を永遠の成長率として使わず、多段階モデルを検討します。長期経済や通貨の物価条件、競争、会社規模に対して無理がないか確認します。gを変える感応度でD0固定かD1固定かも明記すると、表の比較が曖昧になりません。'),
S('配当利回りと成長で要求率を読む','市場価格がモデル価値と一致する仮定ならKe＝D1/P0＋g。価格680、来期配当40.8、g2％なら来期配当利回り6％、合計8％です。過去配当利回り40/680ではなく、式に対応する来期配当を使います。',[['来期配当利回り','40.8/680＝6％','価格に対する配当'],['成長寄与','2％','定率成長の仮定'],['必要率','6＋2＝8％','価格が適正という条件']],'成長部分は確定した利息ではありません。価格上昇が同じgとなるのはモデルの安定した条件下です。実際には評価倍率や配当政策も変わります。高配当利回りが高リスク・減配予想の結果の場合もあるので、単純な収益保証としません。'),
S('使いやすい会社と使いにくい会社','安定利益と持続的な配当政策、成熟した事業で使いやすい一方、無配当、急成長、利益循環、配当の急変では弱いモデルです。Keとgの差が小さいと非常に敏感なので、一点評価ではなく感応度と別のモデルで検証します。',[['適合','安定配当・安定成長','利益と配当の関係を確認'],['不適合','高成長・無配当・大変動','多段階DDMやFCFを検討'],['検証','D1・Ke・gを公開','市場価格を正解と決めない']],'配当は取締役会等の決定と分配可能額・資金条件に依存します。会計利益の一定率を永久に払う前提なら、資本構成とROEの整合も必要です。式の便利さより適用条件を先に確認し、予測と実績を分けて提示してください。')],questions:[Q('D1と価値','D0＝40円、g2％、Ke8％。D1＝D0×1.02、P0＝D1÷（0.08−0.02）。','D1と価値は？','40.8円、680円。'),Q('必要率','価格680円、来期配当40.8円、g2％。価格がモデル値と一致し、Ke＝D1/P0＋g。','Keは？','8％。'),Q('収束条件','成長永久DDMにはKe＞gが必要。Ke8％、g10％、来期配当40円。','公式の負の結果を価値として使える？','使えません。前提が収束条件を満たしていないため、モデルを変えます。')],sources:[ddm]},
{number:13,lead:'最初は高成長、やがて安定成長へ。詳細配当とターミナル価値をつなぎ、価格が織り込む成長も逆算する。',goal:'二段階DDMの終価時点とインプライド成長率を条件付きで計算できる。',sections:[
S('高成長を有限期間に区切る','架空会社はD1＝40円、D2＝44、D3＝48.4と三年成長し、四年目以降は2％成長、Ke8％です。三年の詳細配当と、その後の安定配当を別に評価します。短期10％成長を永久化せず、事業の成熟、競争、必要投資で段階を設定します。',[['詳細期','D1 40・D2 44・D3 48.4','各年末に受取'],['安定初回','D4＝48.4×1.02＝49.368','四年目の配当'],['割引率','Ke8％','全期間一定の簡略仮定']],'移行が急すぎる場合は三段階や徐々に成長が下がるモデルを使います。ここでは計算の時点を学ぶため二段階です。安定期の配当性向、ROE、資本構成が無理なく成長を支えられることも確認してください。'),
S('終価は詳細期末の値','三年末の終価P3＝D4/(Ke−g)＝49.368/0.06＝822.8円。これは今日の値ではないので1.08³で割り引きます。三年目配当48.4は別に加え、四年目配当を詳細期にも足すと二重計上になります。',[['P3','822.8円','年4以降の配当を年3末で評価'],['詳細配当PV','約113.18円','40/1.08＋44/1.08²＋48.4/1.08³'],['終価PV','約653.17円','822.8/1.08³']],'合計価値は約766.35円。表示の丸めで合計にわずかな差が出ることがあるので、計算内部は丸めずに保持します。終価の割合が大きいほど、安定期の仮定が評価を支配します。詳細期が三年だから三年分だけの価値と勘違いしないことが重要です。'),
S('価格が織り込むgを逆算する','一定成長モデルで今期配当D0が既知ならP0＝D0(1＋g)/(Ke−g)よりg＝（P0×Ke−D0）/(P0＋D0)。P0＝680、Ke8％、D0＝40ならg2％です。D1を固定してg＝Ke−D1/P0とする式とは条件が異なります。',[['D0固定','g＝（680×0.08−40）/720','2％'],['D1固定','g＝Ke−D1/P0','来期配当既知の場合'],['解釈','価格から逆算したモデル前提','市場の本当の予測を直接観測していない']],'市場価格にはリスクや配当方針の期待も入るので、逆算gを投資家全員の確定予測としません。Keの推計を変えればgも変わります。インプライド値は、価格を正当化する前提が現実的かを検証する道具として使います。'),
S('段階を増やしても根拠は必要','予測を細かくしても、入力が楽観的なら価値はゆがみます。成長、配当性向、資本効率、競争の四つを合わせ、下振れシナリオを作ります。配当CFを使うので、FCFFのように事業価値から負債を再調整しないことも確認します。',[['予測期間','成熟までの期間','三年固定にする必然性はない'],['安定成長','経済・業種と整合','Ke未満だけでは十分でない'],['検証','終価比率と別モデル','複雑さは精度の証明ではない']],'一年ずつ数字を増やすことより、なぜその年に成長が落ちるかを説明できることが大切です。利益の予測が配当の資金を生むか、更新投資と返済で還元余力が足りるかも見ます。詳細期の終点と安定期の初回を時間軸に並べて復習してください。')],questions:[Q('終価','D3＝48.4円、年4以降g2％、Ke8％。D4＝48.4×1.02、P3＝D4÷（0.08−0.02）。','年3末終価は？','822.8円。'),Q('終価の割引','年3末終価822.8円、Ke8％。今日の終価PV＝822.8÷1.08³。','現在価値は？','約653.17円。'),Q('逆算成長','価格680円、D0＝40円、Ke8％。D0固定のゴードン式でg＝（P×Ke−D0）/(P＋D0)。','gは？','2％。Keとモデルを仮定した逆算値です。')],sources:[ddm]},
{number:14,lead:'ROEと留保率から配当成長を作る。高い留保が価値を生むのは、再投資の収益率が十分なとき。',goal:'サステイナブル成長率とデュポン分解、留保の価値条件を説明できる。',sections:[
S('利益の配分から成長を作る','架空会社のROE12％、配当性向40％なら留保率60％、簡略サステイナブル成長率g＝b×ROE＝7.2％です。資本構成・収益性等を一定とし、外部増資・買付等を省くモデル。計算上の成長率であって、需要や能力を保証する数字ではありません。',[['配当性向','40％','利益のうち配当へ'],['留保率b','60％','1−配当性向'],['g','60％×12％＝7.2％','条件付きの成長']],'ROEは期首・平均など自己資本の定義で変わります。期首資本モデルの関係を、平均ROEから無条件に厳密値として使わないでください。高レバレッジで上げたROEには株主リスクもあるため、成長の持続性を別途確認します。'),
S('ROEを三つに分ける','税引後利益率、総資産回転、自己資本倍率を同じ範囲・期間で掛けるとROEへ分解できます。利益率5％、回転1.2、倍率2ならROE12％。利益率改善、資産効率化、借入増のどれで上がったかによって将来リスクが違います。',[['利益率','5％','利益/売上'],['資産回転','1.2倍','売上/資産'],['資本倍率','2倍','資産/株主資本・ROE12％']],'連結全体の利益と親会社株主資本など、異なる範囲を混ぜると厳密な分解になりません。金融業など事業構造が違う会社も注意が必要です。見た目のROEの高さを評価へ直結させず、利益の質、資産、リスクの原因を検討します。'),
S('留保を増やすと配当は減る','今期EPS100円なら配当性向40％でD0＝40。性向20％へ下げると配当20、留保率80％、同じROE12％ならg9.6％です。短期配当減少と将来成長増加のトレードオフ。Ke8％の永久モデルへg9.6％は入れられないため、段階モデルが必要です。',[['性向40％','D0 40・g7.2％','高い成長は短期条件を検証'],['性向20％','D0 20・g9.6％','配当減・再投資増'],['評価','Ke8％なら永久式不適合','g≧Keで収束しない']],'成長率が高いほど無条件に価値が増えるわけではありません。追加投資の収益率が株主要求率を下回れば、留保が価値を減らす場合があります。既存平均ROEと新規投資ROEを分け、成長のために何の資本が必要かを検討します。'),
S('成長と価値を同時に検証する','配当政策、ROE、借入、増資、買付を一つの自己資本推移表へつなぎます。成熟期はROEや成長を正常化し、永続成長に必要な留保率を逆算します。g3％・ROE10％ならb30％、配当性向70％という簡略関係です。',[['成熟g','3％','永続の仮定'],['成熟ROE','10％','増分収益性を検討'],['必要b','3/10＝30％','配当性向70％']],'実際は自社株買いや希薄化、OCIも自己資本を動かします。留保利益の帳簿残高と手元現金を同じ扱いにしないでください。株主CFと資本推移を合わせて、成長率のために配当を減らした判断が価値を生むかまで説明しましょう。')],questions:[Q('g','ROE12％、配当性向40％、外部増資等なし・条件一定。g＝（1−性向）×ROE。','gは？','7.2％。'),Q('ROE分解','利益率5％、資産回転1.2倍、資本倍率2倍。同じ計算範囲。ROE＝三つの積。','ROEは？','12％。'),Q('必要留保','成熟期g3％、ROE10％、g＝b×ROE。配当性向＝1−b、買付等なし。','留保率と配当性向は？','30％と70％。')],sources:[ddm,nyu]},
{number:15,lead:'株価のうち、既存の稼ぐ力と成長機会はいくらか。成長するだけで価値が増えるわけではない。',goal:'無成長価値とPVGOを計算し、ROEとKeで再投資の価値を説明できる。',sections:[
S('今の利益をすべて還元する基準','将来利益が毎年100円で再投資不要、すべて配当、Ke10％なら無成長価値E1/Ke＝1,000円です。現在株価1,300円ならPVGO＝300円。PVGOは将来成長機会の現在価値を表すモデル上の差で、決算書の現金やのれんと同じ残高ではありません。',[['基準利益E1','100円','永続・全額配当の仮定'],['無成長価値','100/0.10＝1,000円','既存の稼ぐ力'],['株価1,300','PVGO300円','価格との差から逆算']],'現実の維持投資は利益を維持するために必要です。この基準は利益を配当可能とする簡略条件で、設備更新を無視して実務の利益をそのまま使うものではありません。成長価値の解釈にはKeと利益の定義、成長投資の収益性を合わせます。'),
S('ROEがKeより高い再投資','来期EPS100円、Ke10％、留保率40％、新規投資ROE15％が永続という簡略例。g6％、D1＝60円、価値60/(0.10−0.06)＝1,500円。無成長価値1,000との差500が正のPVGOになります。',[['留保b','40％','来期利益のうち再投資'],['成長g','40％×15％＝6％','条件付き'],['価値','60/4％＝1,500円','PVGO500円']],'分子の配当が減っても、十分高い投資収益率が成長の価値を作ります。ただし平均ROE15％が新規投資でも持続するという強い仮定です。追加競争、維持費、資本需要を検証し、モデルのgがKe未満であることも確認します。'),
S('ROEがKe以下なら成長は違う意味','同じEPS100・b40％で新規ROE10％ならg4％、価値60/6％＝1,000。ROE5％ならg2％、価値60/8％＝750でPVGO−250。利益成長が正でも価値を減らす例です。会社が成長を発表しただけで買い判断にはなりません。',[['ROE10＝Ke','g4％・価値1,000','PVGO0'],['ROE5＜Ke','g2％・価値750','PVGO−250'],['ROE15＞Ke','g6％・価値1,500','PVGO＋500']],'負のPVGOは、投資家が会社の再投資を不採算と評価する場合などのモデル解釈です。実際の市場価格が低いとき、利益予測の誤りやリスク推計の差もあり得るため、成長機会が悪いと断定しません。価格とモデルの差を原因ごとに検討します。'),
S('PERへ分けて見る','P/E1＝1/Ke＋PVGO/E1という分解。Ke10％の基準PERは10倍、価格1,300・EPS100ならPER13倍、成長機会分3倍です。高PERが良い成長を表す場合も、単なる楽観や低割引率を表す場合もあります。',[['基準PER','1/0.10＝10倍','無成長部分'],['成長部分','300/100＝3倍','PVGOへの倍率'],['合計','13倍','価格1,300/利益100']],'この分解は価格を説明する道具で、13倍が適正と証明するものではありません。利益の正常化、割引率、配当政策、成長収益性を先に示します。高PERでも再投資が価値を作らないなら前提を見直し、倍率の高さと会社の優劣を切り離して理解します。')],questions:[Q('PVGO','株価1,300円、来期EPS100円、Ke10％。無成長価値＝EPS/Ke、PVGO＝株価−無成長価値。','PVGOは？','300円。'),Q('高収益成長','E1＝100円、b40％、新規ROE15％、Ke10％。g＝b×ROE、D1＝E1×（1−b）、価値＝D1/(Ke−g)。','価値は？','1,500円。'),Q('不採算成長','E1＝100円、b40％、新規ROE5％、Ke10％。g2％、D1 60円、価値＝60/0.08、無成長価値1,000円。','PVGOは？','750−1,000＝−250円。成長が正でも価値は減り得ます。')],sources:[ddm]},
{number:16,lead:'事業が生むFCFFと、株主に残るFCFEは違う。利益から投資と借入まで順に調整する。',goal:'FCFF・FCFEを計算し、対応する割引率と負債調整を説明できる。',sections:[
S('FCFFは全資金提供者のCF','簡略FCFF＝EBIT×（1−T）＋償却−Capex−NWC増。架空会社のEBIT100・税率30％・償却20・Capex40・NWC増10（億円）なら40。利息を引かないのは株主と債権者全体の事業CFを測るためです。',[['NOPAT','100×0.7＝70','税引後営業利益'],['非現金・投資','＋20−40−10','償却加算・資金拘束控除'],['FCFF','40億円','WACCで割り引く']],'実務は非事業項目、一時費用、税、リース、買収等の定義を調整します。営業CFから算出する場合、利息支払の表示区分や税率も確認します。償却の加算で過去設備が無料になるわけではなく、必要な維持・成長投資をCapexに含めます。'),
S('FCFEは株主側へ絞る','FCFE＝純利益＋償却−Capex−NWC増＋純借入。支払利息10・税率30％・他損益なしなら純利益（100−10）×0.7＝63。新規借入15・元本返済5なら純借入10、FCFE43です。元本返済は利益の費用ではなくCF調整です。',[['純利益','63','利息と税の後'],['投資調整','＋20−40−10','FCFFと同じ投資'],['純借入','15−5＝10','FCFE63＋20−40−10＋10＝43']],'FCFEがFCFFより大きいのは矛盾ではありません。この例では税引後利息7より純借入10が大きいからです。借入による一時的な株主CF増を永続成長と誤認しないでください。将来の返済とKe上昇、目標負債構成も予測へ反映します。'),
S('二つのCFの橋を照合する','FCFE＝FCFF−税引後利息＋純借入。40−10×0.7＋10＝43。利益から計算した結果と一致します。税盾が利用できないなどの場合にはこの簡略関係の税調整を見直します。FCFを会社が独自に定義している場合も同じか確認します。',[['出発FCFF','40','資金調達前'],['税引後利息','−7','株主前の債権者負担'],['純借入','＋10','株主CF43へ']],'会社が「フリーCF＝営業CF＋投資CF」と表示する場合、買収・利息・証券売買等が含まれ、FCFFと一致しないことがあります。同じ名前だけで値をコピーせず、本文の計算式と決算資料の範囲を照合します。受益者と定義を横に記載してください。'),
S('評価の出口まで対応させる','FCFFをWACCで評価すると事業価値で、事業外資産・負債等を調整して株式価値へ移します。FCFEをKeで評価すれば直接株式価値なので負債を再度引きません。両方法が整合するにはCF、負債政策、割引率の対応が必要です。',[['FCFF→WACC','事業価値','負債等を後で調整'],['FCFE→Ke','株式価値','負債を重ねて引かない'],['一致条件','同じ事業・調達予測','安定負債比率等を確認']],'FCFEは負債政策の変化で大きく変動し、成長会社では負になることもあります。その場合は詳細予測を長くするなど、安定期への道筋を検証します。マイナスの一年度だけで価値ゼロとせず、投資と借入の原因を分けて説明します。')],questions:[Q('FCFF','EBIT100・T30％・償却20・Capex40・NWC増10（億円）。FCFF＝EBIT×0.7＋償却−Capex−NWC増。','FCFFは？','40億円。'),Q('FCFE','純利益63・償却20・Capex40・NWC増10・新借入15・元本返済5（億円）。FCFE＝利益＋償却−投資−NWC増＋新借入−返済。','FCFEは？','43億円。'),Q('橋の検算','FCFF40・利息10・税率30％・純借入10（億円）。FCFE＝FCFF−利息×（1−T）＋純借入。','FCFEは？','40−7＋10＝43億円。')],sources:[fcf]},
{number:17,lead:'DCFのCFをどこから作るか。売上・利益率・運転資本・設備投資を同じ予測表につなぐ。',goal:'事業予測からFCFFを作り、売上成長だけの楽観評価を避けられる。',sections:[
S('売上は数量・価格・構成から','架空会社の基準売上1,000億円、翌年成長10％で1,100とします。成長率は計算仮定で、実在企業の予想ではありません。実務では数量、単価、顧客、シェア、地域、買収などから作り、同じ増収でも原因と持続性を分けます。',[['基準年','売上1,000','確定実績に相当する仮定'],['年1予測','1,000×1.10＝1,100','予測成長10％'],['確認','数量・単価・事業構成','一律成長を永久化しない']],'売上予測には生産能力や人員の制約もあります。市場全体が伸びるとしても自社が同じ率で伸びるとは限りません。名目売上を使うなら名目割引率を使い、外貨売上の通貨変換や連結範囲も統一します。まず上振れと下振れの理由を言葉にします。'),
S('営業利益率を費用に結び付ける','翌年営業利益率12％ならEBIT132億円、税率30％でNOPAT92.4。販管費、原価、稼働率、価格転嫁、研究開発から率を説明します。成長と同時に率を上げるなら、設備や人員への投資負担が増えないかを検証します。',[['売上','1,100','前節の予測'],['EBIT','1,100×12％＝132','事業利益'],['NOPAT','132×0.7＝92.4','事業税引後・税率仮定']],'税引後事業利益に純利益の実効税率を無条件に使うと、金融損益や特別項目を混ぜる場合があります。税盾と欠損の利用可能性も確認します。利益率の前年差は「効率化」で済ませず、どの費用がいくら変わるか表にして説明します。'),
S('NWC残高から増加額を作る','営業NWCを売上の15％と仮定すると基準150、翌年165、増加15億円。FCFFから引くのは翌年残高165ではなく増加15です。償却30、Capex50ならFCFF＝92.4＋30−50−15＝57.4億円になります。',[['NWC基準','1,000×15％＝150','残高'],['NWC翌年','1,100×15％＝165','増加15'],['FCFF','92.4＋30−50−15＝57.4','投資と資金拘束後']],'売掛金回収日数、在庫日数、買掛金日数から予測する方が事業に合う場合もあります。負のNWCモデルもあり、売上比率だけが正解ではありません。Capexを償却と同額に固定するなら、生産能力や維持・成長投資と整合する理由を確認します。'),
S('予測を価値へ移す前に検算する','PL、BS、CFをつなぎ、借入、現金、配当が無理なく推移するかを確認します。詳細期のFCFFを各年割引し、安定期の終価を最後の詳細年末で評価します。将来の事業CFへ支払利息を引き、WACCも使う二重反映を避けます。',[['整合','売上→利益→NWC→設備→CF','一つの事業予測'],['感応度','成長・率・投資・WACC','変化の理由を示す'],['出口','事業価値→株式→一株','負債・現金・株数を確認']],'DCFの小数点が細かくても、入力の精度が高いとは限りません。売上10％、利益率12％などは仮定と表示し、確認すべき受注や顧客行動を記録します。計画より資金需要が増えた場合の調達と、価値がどれだけ変わるかも検討しましょう。')],questions:[Q('NOPAT','予測売上1,100億円、営業利益率12％、税率30％。EBIT＝売上×率、NOPAT＝EBIT×0.7。','NOPATは？','92.4億円。'),Q('NWC増','基準売上1,000・翌年1,100億円、両年NWC比率15％。増加＝翌年残高−基準残高。','NWC増は？','165−150＝15億円。'),Q('FCFF','NOPAT92.4・償却30・Capex50・NWC増15（億円）。FCFF＝NOPAT＋償却−Capex−NWC増。','FCFFは？','57.4億円。')],sources:[forecast,fcf]},
{number:18,lead:'DCFの大半を終価が占めることがある。永続成長・割引率・出口倍率の前提を表で確かめる。',goal:'終価の時点と感応度を計算し、終価への過大依存を説明できる。',sections:[
S('詳細CFと終価を並べる','架空会社の年1FCFF100、年2 110、年3 120（億円）、WACC10％、年4以降g2％。三年末終価＝120×1.02/(0.10−0.02)＝1,530。これを年3末の値として三回割り引き、三年分CFのPVへ加えます。',[['年1〜3のCF','100・110・120','各年末回収'],['年4CF','122.4','安定期初回'],['年3末終価','1,530','年4以降をまとめた値']],'合計事業価値は約1,421.49億円です。終価1,530を今日の価値としてそのまま足すと過大評価になります。三年目CF120は終価の中の初回ではないので、詳細CFと終価を分けます。会社が三年で終わるという意味ではありません。'),
S('成長率と割引率の差を動かす','感応度の簡略比較で来期FCFF100を固定すると、WACC8％・g2％で永続価値1,666.67、WACC10％・g2％で1,250、WACC10％・g3％で1,428.57億円。gを上げるだけで価値が大きく変わるため、前提の根拠が必要です。',[['r8・g2','100/0.06＝1,666.67','終価時点の値'],['r10・g2','100/0.08＝1,250','率上昇で価値低下'],['r10・g3','100/0.07＝1,428.57','来期CF固定の感応度']],'この表は三年前節と別のC1固定比較です。現実ではgを上げると必要再投資が増え、FCFFも変わります。安定ROIC10％でg2％なら再投資率20％、g3％なら30％。成長だけ上げCFを固定する表の限界を明示してください。'),
S('出口倍率は市場に依存する','三年末EBITDA200にEV/EBITDA8倍を掛ければ終価1,600億円です。これは市場倍率法の仮定で、成長永久年金の独立した証明ではありません。倍率が景気ピーク、金利、会計定義に依存する点と、DCFと時点・範囲をそろえる点が重要です。',[['出口利益','年3EBITDA200','終価時点の指標'],['出口倍率','8倍','比較会社等の仮定'],['終価','200×8＝1,600','現在へ三回割引']],'年4予想倍率を使うなら、対応する年4利益と評価時点の定義を示します。EBITDAの定義、リース、非支配持分、維持投資の違いも調整します。都合の良い高倍率を選び、永続法と平均すれば安全になるという考え方は避けましょう。'),
S('終価比率と前提の整合を見る','最初の三年モデルでは終価PV約1,149.51、事業価値約1,421.49で終価比率約80.87％。高いこと自体が誤りとは限りませんが、詳細期だけを丁寧にしても安定期が雑なら評価は弱くなります。成熟期の投資・利益・成長をまとめて検証します。',[['終価PV','1,530/1.1³≈1,149.51','現在価値'],['比率','1,149.51/1,421.49≈80.87％','終価への依存'],['検証','WACC・g・ROIC・再投資','KeとFCFFを混ぜない']],'予測期間を延長すれば必ず精度が上がるわけではありません。安定状態に達するまでの合理的な期間を設定します。事業価値から負債・現金等を調整して一株価値へ移し、価格との乖離がどの仮定で生まれるかを説明できるようにします。')],questions:[Q('終価','年3FCFF120、年4以降g2％、WACC10％。年3終価＝120×1.02/(0.10−0.02)。単位億円。','終価は？','1,530億円、年3末の価値です。'),Q('現在へ戻す','年3末終価1,530億円、WACC10％。終価PV＝1,530/1.1³。','PVは？','約1,149.51億円。'),Q('再投資の整合','安定成長g3％、増分ROIC10％。g＝再投資率×ROIC、必要再投資率＝g/ROIC。','必要再投資率は？','30％。成長を上げても再投資を据え置くと不整合になり得ます。')],sources:[fcf,forecast,multiple]},
{number:19,lead:'簿価に将来の超過利益を足して評価する。PBRとROE、株主資本コストの関係を理解する。',goal:'残余利益と一期間モデル、安定期の正当化PBRを条件付きで計算できる。',sections:[
S('株主資本にも費用を課す','一株残余利益RI＝EPS−Ke×期首BPS。架空会社のB0 1,000円・来期EPS120円・Ke8％なら資本費用80、RI40円です。会計黒字120の全部が超過利益ではありません。事業側のNOPATとWACCを使う経済利益とは受益者が違います。',[['期首BPS','1,000円','株主簿価'],['資本費用','1,000×8％＝80円','株主の機会費用'],['残余利益','120−80＝40円','要求を超える利益']],'利益は普通株主に帰属する範囲をそろえます。OCI、会計変更、自己株式などで簿価が動くため、クリーンサープラス関係に必要な調整を検討します。簿価を必ず現金化できるという意味ではなく、会計と将来利益から価値を作るモデルです。'),
S('簿価とRIのPVを足す','株式価値P0＝B0＋将来RIのPV。年1だけRI40、その後はRI0、Ke8％ならP0＝1,000＋40/1.08＝約1,037.04円。年2以降に利益ゼロという意味ではなく、利益が株主資本コストをちょうど満たす前提です。',[['基準簿価','1,000','モデルの出発点'],['年1RIのPV','40/1.08≈37.04','一年後の超過利益'],['一株価値','1,037.04','年2以降RI0の仮定']],'簿価だけに将来純利益を足すと、資本の機会費用を二重に扱って過大になり得ます。DDMやFCFEと整合するには利益、配当、簿価推移、割引率が一致している必要があります。無配当や負のCFが続く会社でも利益を予測できれば使う候補になります。'),
S('正当化PBRをROEから読む','安定ROE、成長、配当とクリーンサープラスが整合する簡略モデルでP/B＝（ROE−g）/(Ke−g)。ROE12％、Ke8％、g2％ならPBR約1.67倍です。ROEがKeと同じなら1倍、低ければ1倍未満となる条件付き関係です。',[['ROE12・Ke8・g2','（0.12−0.02）/0.06≈1.67','超過利益がある'],['ROE8・Ke8・g2','0.06/0.06＝1','超過利益0'],['ROE6・Ke8・g2','0.04/0.06≈0.67','要求率を下回る']],'実際のPBR1倍割れを必ず割安と判断しません。資産の過大簿価、将来の低ROE、高リスク、成長投資の不採算などの可能性があります。ROEを改善する買付や減損が経済価値を増やしたか、分母が減っただけかを確認します。'),
S('会計の質と持続性を検証する','残余利益モデルは利益と簿価の質に敏感です。研究開発、のれん、リース、減損、OCI、一時利益、非支配持分の範囲を確認します。高ROEを永続させず、競争で超過利益が消える期間を設定することも重要です。',[['利益調整','正常EPS・一時項目','資本費用の範囲と一致'],['簿価調整','資産回収・OCI等','過大・過小を検討'],['継続RI','持続期間・収束','楽観的な永久化を避ける']],'モデル間の差が出たとき、単純平均より前提を照合します。FCFの投資予測と簿価の成長が一致しているか、配当と留保が自己資本をつないでいるかを確認します。RIは会計黒字の裏にある株主の必要補償を見える形にする道具です。')],questions:[Q('RI','期首BPS1,000円、EPS120円、Ke8％。RI＝EPS−Ke×BPS。','RIは？','40円。'),Q('一年RIモデル','B0 1,000円、年1RI40円、年2以降RI0、Ke8％。P0＝B0＋40/1.08。','価値は？','約1,037.04円。'),Q('正当化PBR','安定・会計整合を仮定。ROE12％、Ke8％、g2％。P/B＝（ROE−g）/(Ke−g)。','PBRは？','約1.67倍。')],sources:[residual]},
{number:20,lead:'似た会社の倍率を使う。でも業種名が同じだけでは足りない。成長・採算・負債・会計差を調整する。',goal:'類似企業比較で株式価値と事業価値の倍率を使い分け、中央値の限界を説明できる。',sections:[
S('比較会社の条件を先に決める','類似企業比較は、市場が他社をどう評価しているかを参考にします。事業、地域、成長、利益率、資本効率、リスク、会計を比較します。同業という名称だけで一緒にしないでください。倍率が異なる理由を説明できて初めて評価に使えます。',[['事業','顧客・製品・地域','需要と競争を比較'],['財務','成長・利益率・資本・負債','同じ倍率の適用が妥当か'],['データ','評価日・予想期・会計','同じ条件にそろえる']],'株価は評価日時点、利益は同じ予測年度にします。過去の低利益と他社の来期予測利益を混ぜると倍率差を誤解します。一時益や赤字、買収による連結範囲変化も点検し、採用・除外の基準を記録します。'),
S('PER法で株式価値を求める','架空比較会社の来期PERが10・12・20倍なら中央値12倍。対象の正常来期株主利益50億円へ掛けると株式価値600億円です。株主側倍率なので負債をさらに引きません。対象の高成長や高リスクに応じて12倍の適用が合理的かを検討します。',[['比較倍率','10・12・20','中央値12'],['対象利益','50億円','普通株主の正常利益'],['株式価値','50×12＝600億円','PER法の推計']],'三社の平均14倍と中央値12倍は違います。外れ値20を都合よく除くのではなく、成長、利益品質、データ不備などの理由を説明します。赤字企業へ負のPER中央値を掛ける方法は適切ではなく、別の指標を検討します。'),
S('EV倍率から株式へ橋を架ける','比較EV/EBITDA6・7・9倍の中央値7を、対象EBITDA100億円へ掛けると事業側価値700。事業外現金50・負債200のみなら株式価値550億円です。優先株、非支配持分、リース等があれば追加対応を確認します。',[['EV推計','100×7＝700','事業側の倍率'],['調整','現金＋50・負債−200','本問の簡略定義'],['株式価値','550億円','PER法の600とは別推計']],'EBITDAの調整やリース定義を比較企業とそろえます。設備投資が大きい会社と軽い会社で同じ倍率を使うとCF差を無視する可能性があります。純負債調整と利益指標の範囲、連結範囲を一つの表にして確認します。'),
S('相対的な安さと絶対的な価値は違う','同業がすべて楽観的に評価されていれば、相対的に低倍率でも割安とは限りません。DCFやRIで将来CFと必要収益率を検証します。倍率差を全部成長で説明せず、リスク、資本効率、会計、ガバナンスも考えます。',[['相対評価','比較会社の市場価格が基準','市場全体の割高を含み得る'],['絶対評価','将来CFと要求率','予測誤差がある'],['総合判断','差の原因と範囲を提示','複数モデルの平均は保証でない']],'モデル値600と550の差は、一つが必ず誤りとは言えません。利益と償却・投資、選んだ倍率、負債調整を照合し、なぜ差があるか説明します。投資家へは一点価格の断言より、前提と比較可能性の限界を示すことを重視しましょう。')],questions:[Q('中央値PER','比較来期PER10・12・20倍、対象正常来期株主利益50億円。中央値を採用し価値＝利益×倍率。','株式価値は？','600億円。'),Q('EV法','対象EBITDA100億円、採用EV倍率7倍、現金50・負債200、他調整なし。株式＝EBITDA×倍率＋現金−負債。','株式価値は？','550億円。'),Q('平均と中央値','PER10・12・20倍。平均＝合計/3、中央値＝小さい順の中央。','各値は？','平均14倍、中央値12倍。採用理由を示します。')],sources:[multiple]},
{number:21,lead:'赤字成長企業、景気敏感企業、資産を多く持つ企業。同じPERを当てず、利益と資産の意味からモデルを選ぶ。',goal:'企業タイプに応じた正常化・予測期間・評価法を選び、指標の限界を説明できる。',sections:[
S('赤字企業は売上倍率だけで終わらない','成長企業が先行費用で赤字ならPERは使いにくく、売上、顧客継続、粗利、獲得費、黒字化後のCFを検証します。PSRが低いから割安とは限りません。売上1,000億円で将来利益率10％か2％かでは、株主の回収力が大きく違います。',[['高採算シナリオ','売上1,000×10％＝利益100','将来への仮定'],['低採算シナリオ','1,000×2％＝20','同じ売上でも利益五分の一'],['評価','黒字化と追加投資・希薄化','長い予測には大きい誤差']],'顧客を増やすための現金流出が続くなら、追加調達と持分低下を予測します。赤字が一時費用なのか、販売するほど損失が増える構造なのかを分けます。売上倍率を使う場合も、将来利益率・成長・リスクの条件を明示してください。'),
S('景気敏感企業は正常利益を探す','架空会社の一サイクル利益20・80・140億円の平均80。株式価値1,120ならピークPER8倍、正常利益PER14倍、底PER56倍です。ピークで低PER、底で高PERに見えるため、単年の倍率だけで割安を判断すると逆になり得ます。',[['ピーク利益140','1,120/140＝8','低倍率に見える'],['正常利益80','PER14','簡略三期平均'],['底利益20','PER56','高倍率に見える']],'三期平均は演習の仮定で、現実のサイクルが三年とは限りません。設備増減、物価、買収、構造改革で利益の基準が変わる場合、過去平均をそのまま使えません。数量、価格、稼働率、維持投資から中間的な採算を検証します。'),
S('資産株は回収可能額で見る','架空会社の簿価資産500億円、実現可能額420、負債300、処分費20なら株主回収可能額100。簿価純資産200より小さく、株式価格120ならPBR0.6でも清算価値基準では必ず安いとは言えません。事業継続価値とは別の推計です。',[['簿価純資産','500−300＝200','会計の差額'],['処分後株主残余','420−300−20＝100','税等は本例で省略'],['価格120','PBR0.6','回収価値100より高い']],'資産の売却に時間がかかる、担保や契約で処分できない、税金が生じるなども考慮します。含み益だけでなく含み損や退職債務を確認します。資産があることと株主が自由に現金化できることは違うので、ガバナンスや再編可能性も評価に影響します。'),
S('モデルを選んだ理由を説明する','安定配当ならDDM、事業CF予測ならFCFF、株主CFならFCFE、利益と簿価が使えるならRI、類似市場評価なら倍率法が候補です。金融会社は負債が事業そのものなので、一般企業のEV/EBITDAを機械的に使わないようにします。',[['モデル選択','CF・利益・簿価の予測可能性','都合の良い価格を選ばない'],['正常化','一時項目・サイクル・会計','根拠と範囲を残す'],['照合','別モデルと感応度','差の原因を検証']],'複数モデルが同じ値でも、共通の楽観的前提なら誤りは残ります。将来の不確実性が大きいほど値幅を示し、実現条件と反証指標を記録します。会社タイプは入口の分類であり、実際の事業と最新資料を確認する代わりにはなりません。')],questions:[Q('正常PER','一サイクル利益20・80・140億円、正常利益は単純平均、株式価値1,120億円。正常PER＝価値÷平均利益。','正常PERは？','14倍。ピークPER8倍とは違います。'),Q('回収価値','実現資産420、負債300、処分費20（億円）、税・他請求なし。株主残余＝420−300−20。','株主回収額は？','100億円。'),Q('売上倍率の限界','同じ売上1,000億円。A予想利益率10％、B2％。利益＝売上×利益率。すべて予測仮定。','利益は同じ？','違います。A100億円、B20億円。PSRだけでは採算差を評価できません。')],sources:[multiple,fcf,residual]},
{number:22,lead:'割引率は小さな入力差でも価値を変える。市場プレミアムとベータの推計条件、CFとの対応を確認する。',goal:'ベータ推計と要求率を区別し、Ke・WACCをモデルに正しく対応させられる。',sections:[
S('リスクプレミアムは推計値','株式リスクプレミアムERPは、株式市場の期待収益率が安全利率を上回る部分です。過去平均、アンケート、市場価格からの逆算などで推計できますが、同じ値を必ず得るわけではありません。過去の実現平均を今後の確定収益率と表現しないでください。',[['過去推計','過去の市場収益−安全率','標本・期間に敏感'],['将来推計','利益・配当・価格から逆算','モデルと予測に依存'],['使用','通貨・市場・時点を明記','計算仮定を最新値と混同しない']],'長いデータでも制度や経済構造が変わる場合があります。算術平均と幾何平均、短期の安全率と長期金利で差が出ます。ERPを一つの数字としてコピーせず、用途と推計方法を示し、評価でどのくらい影響するかを感応度で確認します。'),
S('ベータは回帰の傾き','収益率を市場指数収益率へ回帰し、傾きをベータとして推計します。共分散0.018・市場分散0.015ならβ1.2。配当・分割調整、週次か月次か、観測期間、市場指数で変わるので、公式な固定値ではありません。薄商いにも注意します。',[['共分散','0.018','同じ頻度の小数収益率'],['市場分散','0.015','共分散と同じ単位'],['β','0.018/0.015＝1.2','推計の不確実性がある']],'過去ベータを将来へ使うなら、事業構成や負債比率の変化を確認します。比較企業をアンレバーして自社目標構成へ再レバーする方法もあります。全社ベータでリスクの違う部門や新規事業を評価しないよう、評価対象に対応させます。'),
S('Keの入力変化を並べる','架空のRf2％・β1.2・ERP5％ならKe8％。ERP6％ならKe9.2％、β1.5・ERP5％ならKe9.5％です。すべて仮定で最新市場値ではありません。収益予測を下げるリスクと割引率上乗せを同じ理由で重ねていないかも確認します。',[['基準','2＋1.2×5＝8％','CAPMの必要率'],['ERP6','2＋1.2×6＝9.2％','プレミアム推計差'],['β1.5','2＋1.5×5＝9.5％','事業・負債感応度差']],'国リスクや流動性等を追加する場合は、既にCFやERPに入っていないか確認します。リスクが高いから何％でも足すという方法は説明力が弱くなります。名目・実質、税引前後、通貨、期間の対応を先にそろえ、モデルの限界を記録します。'),
S('CFと割引率の組を固定する','DDMとFCFEはKe、FCFFはWACCを使います。借入政策が変われば両方の率とCFが変わり得ます。一期間後100のPVはKe8％で92.59、9.2％で91.58。同じCFの感応度と、事業予測も変えたシナリオを区別します。',[['株主CF','配当・FCFE','Keで評価'],['事業CF','FCFF','WACCで評価'],['感応度','CF固定で率だけ変更','実際の複合変化とは違う']],'細かい小数点の割引率に確信を置かず、合理的な範囲を示します。入力データの基準日、推計と仮定、比較企業の調整を残すと、価格や事業が変わったとき更新できます。割引率は結論を合わせるための調整弁ではなく、リスクの必要補償です。')],questions:[Q('ベータ','共分散0.018、市場分散0.015、同じ頻度・単位。β＝共分散÷市場分散。','βは？','1.2。'),Q('Ke','Rf2％、β1.2、ERP6％。Ke＝Rf＋β×ERP。すべて計算仮定。','Keは？','9.2％。'),Q('CFの対応','配当とFCFEは株主CFでKe、FCFFは事業CFでWACC。Ke9.2％、WACC7％という仮定。','配当を割る率は？','Ke9.2％。')],sources:[capm,fcf]},
{number:23,lead:'公開情報から簡単に儲かるのか。市場効率性の三形態と、アクティブ・パッシブ運用の条件を考える。',goal:'弱形・準強形・強形を情報集合で区別し、効率性の誤解を説明できる。',sections:[
S('何の情報を織り込むか','市場効率性は情報が価格へどう反映されるかの仮説です。弱形は過去の価格等、準強形は公開情報、強形は非公開情報も含む情報集合を考えます。強形は現実の理想条件として非常に強く、インサイダー情報で取引してよいという意味ではありません。',[['弱形','過去価格・取引情報','それだけの予測優位を検討'],['準強形','公開情報','決算・ニュースの反映'],['強形','公開・非公開情報','現実で強い仮定']],'効率的なら株価は動かない、という理解は誤りです。新しい情報が来れば価格は動きます。将来が確定している、すべての価格が常に正しい、という意味でもありません。どの情報が、どの速さと費用で価格に反映されるかを分けて考えます。'),
S('分析の必要性と無料の超過収益は別','多くの投資家が分析と売買を行うことで価格発見が進みます。一方、公開情報だけで費用控除後に継続超過収益を得られるかは別の問いです。見つけた割安が既に織り込まれている、取引費用で消える、単なるリスク補償だった可能性を検証します。',[['価格発見','分析・売買が情報を反映','分析が無意味とは言わない'],['超過収益','適切なリスク調整後','高リターン＝能力とは限らない'],['費用','調査・手数料・インパクト','利益から差し引く']],'過去に良い戦略を多数探索すると、偶然の成功を選びやすくなります。テスト用と検証用の期間を分け、当時知らなかった情報を使う先読みを避けます。効率性を信じるか否かだけでなく、再現可能な検証の方法を学ぶことが重要です。'),
S('アクティブとパッシブを比べる','パッシブは指数等への連動を目指し、アクティブは銘柄・配分等で超過を狙います。架空のアクティブ総収益9％・総費用1.5％なら純7.5％、指数8％より0.5ポイント下。総収益だけの比較は投資家の結果を誤解します。',[['総収益','9％','費用控除前'],['純収益','9−1.5＝7.5％','簡略の年率近似'],['指数8％','純超過−0.5ポイント','リスク・期間もそろえる']],'パッシブにも費用、追随誤差、構成集中、入替売買があります。アクティブはどの情報優位と投資制約で価値を作るかを示します。どちらも利益を保証しないので、投資家の期間、負債、損失許容、運用コストと合わせて判断します。'),
S('価格のゆがみは原因と制約を見る','行動バイアス、資金制約、取引規制、流動性、情報コストで価格がずれる場合があります。しかし裁定には資金と時間が必要で、収束前に損失が拡大することもあります。見かけのアノマリーをすぐ実行可能な収益源としないでください。',[['原因','過剰反応・制約・情報不足','仮説を具体化'],['検証','費用・リスク・外部標本','探索バイアスを抑える'],['実行','売買可能性・資金・収束時間','机上の利益と区別']],'市場効率性の議論は、価格を絶対に正しいか間違いかに二分するものではありません。情報集合、リスク調整、費用、検証期間を明示し、どの条件で優位があるかを考えます。法律と倫理を守ることは、効率性の仮説とは別の必須条件です。')],questions:[Q('三形態','弱形＝過去価格等、準強形＝公開情報、強形＝非公開情報も含む。最新公表決算がすぐ価格へ反映される仮説。','どの形態の論点？','準強形です。'),Q('費用控除','運用総収益9％、総費用1.5％、指数8％。本問の純収益＝総−費用、超過＝純−指数。','純収益と超過は？','7.5％、−0.5％ポイント。'),Q('新情報','効率市場では利用可能情報を価格に反映する。今朝、予想外の悪材料が公表された。','株価下落は効率性に反する？','必ずしも反しません。新情報の反映で価格が変わることは整合的です。')],sources:[cfa('market-efficiency','Market Efficiency')]},
{number:24,lead:'バリュー・サイズ・モメンタムなどの共通特性で株をまとめる。ファクター収益と運用者の能力を分ける。',goal:'株式ファクターとスマートベータ、スタイル分析の基本とリスクを説明できる。',sections:[
S('銘柄の後ろに共通特性がある','株式ファクターは、価格変動や収益を説明する共通特性です。市場、サイズ、バリュー、モメンタム、クオリティ、低ボラティリティなどを使います。定義は研究や商品で異なるため、ファクター名だけで同じ戦略と判断しないでください。',[['バリュー','利益・簿価等に対し低い価格','割安の罠や業種偏りもある'],['モメンタム','一定期間の上昇傾向','急反転で損失の恐れ'],['クオリティ','採算・安定・財務等','測定指標・範囲が異なる']],'歴史的にプレミアムが見えたことと、今後必ず儲かることは別です。リスク補償、行動、取引制約、データ探索など複数の説明があり得ます。業種、国、通貨、負債への偏りも確認し、一つの因子で安全性を断定しません。'),
S('スマートベータはルールを公開する運用','時価加重以外の重みやファクターへのエクスポージャーを、体系的なルールで実装する運用をスマートベータと呼びます。等金額、最小分散、指標加重などは目的が違います。指数という名前でも、設計には選択と再配分があります。',[['等金額','各銘柄を同じ金額へ','小型株・入替の影響'],['低リスク型','分散やボラを抑える設計','推計誤差・業種偏り'],['因子型','特性に基づく銘柄・重み','定義・頻度・費用を確認']],'バックテストは実運用と同じではありません。生存銘柄だけを使う偏り、先読み、当時の売買費用、容量、入替時の価格影響を確認します。規則が公開されると売買が混雑することもあるため、理論収益と実行可能収益を分けます。'),
S('ファクターで超過収益を分解する','架空運用の収益10％、安全率2％、市場寄与5、バリュー寄与2ならモデル説明は9％、残りアルファ1ポイント。市場やバリューのリスクを取った報酬を全部運用者の能力としません。寄与は感応度×因子収益として算出済みという条件です。',[['安全率＋因子寄与','2＋5＋2＝9％','モデルで説明'],['実収益','10％','同じ期間の架空結果'],['残差α','10−9＝1ポイント','モデル依存・費用前後も確認']],'因子を追加すればアルファ推計が変わります。統計的有意性、安定性、期間、費用控除を確認します。残差がプラスだから将来の能力が確定するわけではありません。スタイルの変化や対象市場の違いを含め、運用者のプロセスも評価します。'),
S('因子を分散しても共通損失は残る','複数因子を組み合わせると変動を抑える可能性がありますが、相関は時期で変わります。割安株と小型株が同時に損失、モメンタムが急反転などのリスクを検討します。長期の低迷に投資家が耐えられるか、資金使用時期も重要です。',[['複合因子','異なる収益源を組合せ','相関推計に不確実性'],['実装費用','入替・手数料・インパクト','高頻度ほど負担増も'],['運用適合','期間・損失許容・容量','過去成績だけで選ばない']],'戦略を比較するときは、指数の算出日、リバランス、除外条件、配当、税、通貨をそろえます。ファクターは価格や運用成績を理解する道具で、必勝パターンではありません。どの特性、どのリスク、どの費用を負っているかを説明してください。')],questions:[Q('アルファ分解','実収益10％、安全率2％、市場寄与5％ポイント、バリュー寄与2ポイント。同期間、残差α＝実−安全率−寄与。','αは？','1％ポイント。モデルによる分解です。'),Q('費用後超過','ルール運用の費用前収益8％、費用1％、比較指数7.5％。本問純＝総−費用。','費用後超過は？','7−7.5＝−0.5％ポイント。'),Q('等金額','二銘柄の総予算100万円、等金額配分。A株価1,000円、B500円、端数・費用なし。各予算50万円。','各株数は？','A500株、B1,000株。等株数ではありません。')],sources:[capm,['CFA Institute Research Foundation：The Active Side of Indexing','https://rpc.cfainstitute.org/research/foundation/2026/active-side-indexing'],nyu]},
{number:25,lead:'注文を分けるアルゴリズムと、高速に売買するHFTは同じ意味ではない。目的・費用・障害リスクを整理する。',goal:'執行アルゴとHFTの役割を区別し、取引の自動化に必要な管理を説明できる。',sections:[
S('アルゴ取引は目的とルールを見る','アルゴリズム取引は、条件やプログラムで注文・売買を行う広い概念です。長期投資の大量注文を少しずつ執行する方法も、短期シグナル取引も含まれます。HFTは高速・高頻度の特徴を持つ活動で、すべてのアルゴがHFTではありません。',[['執行アルゴ','決めた注文を分割する','価格影響と時間を調整'],['戦略アルゴ','条件から売買判断を行う','予測・リスクの検証が必要'],['HFT','高速の注文・取引活動','目的・影響は戦略で違う']],'自動化しただけで市場を予測できるようになるわけではありません。入力データ、モデル、注文制限、障害時の停止が必要です。速度への投資と得られる便益も比較し、手動の監督を不要と考えないでください。AIモデルでも同じ基本管理が必要です。'),
S('TWAP・VWAP・参加率を比べる','TWAPは時間に沿って分け、VWAPは想定出来高の分布に沿って配分し、参加率型は市場出来高の一定割合などを目指します。架空注文1万株を五区間の等時間へ分けるなら各2,000株。市場の実出来高が想定と違えば調整が必要です。',[['TWAP','五区間に各2,000株','単純な等時間モデル'],['VWAP型','出来高多い区間に多く配分','予測分布に依存'],['参加率型','市場1万株に10％なら1,000株','上限・未約定も管理']],'大量注文を細かくしても、合計の市場影響が消えるとは限りません。長く待てば情報漏れや価格変動リスクが増えます。目的はどのベンチマーク、期限、価格制約を優先するかなので、万能の最良アルゴはないと理解します。'),
S('HFTの便益とリスクを分ける','高速のマーケットメイク等が流動性を提供する場合がある一方、急な撤退や注文集中、技術障害がリスクになります。高速な注文がすべて不正という理解も、常に市場を良くするという理解も不適切です。行為とルールと影響を検証します。',[['便益候補','競争・価格発見・流動性','銘柄・時間で違う'],['リスク','障害・集中・急な撤退','ストレス時を検証'],['規制・管理','登録・注文管理等','適用法令・参加者ルールを確認']],'見せ玉や相場操縦などの禁止行為は取引速度とは別に問題です。注文の理由と実行可能性、記録、監視を整える必要があります。この発展講義は取引システムの開発手順ではなく、市場構造と運用管理を理解する入口です。'),
S('実装前と障害時の統制','価格・数量の上限、重複注文、異常データ、接続断、ポジション限度を確認します。シミュレーションだけでなく、小さい実行、監視、停止、復旧、事後照合が必要です。注文失敗の再送で二重発注しない管理も重要になります。',[['事前','価格・数量・資金の限度','誤注文を止める'],['運転中','約定・ポジション・異常監視','停止権限を明確にする'],['事後','注文と約定の照合','ログ・原因・改善を残す']],'テスト時には実注文を出さず安全な環境で検証し、法令と社内承認を守ります。モデルの学習精度と執行の安全性は別の評価です。市場インパクト、情報、技術、法規の四層を並べ、自動化が新しく生むリスクまで説明してください。')],questions:[Q('TWAP配分','1万株を五つの等時間区間へ均等配分。端数・費用なし。一期株数＝総株数÷区間数。','各区間は何株？','2,000株。'),Q('参加率','市場出来高1万株、目標参加率10％。本問の対象株数＝出来高×参加率、他制約なし。','対象株数は？','1,000株。'),Q('アルゴとHFT','アルゴはプログラムによる広い取引・執行、HFTは高速・高頻度の特徴。長期注文を一日で少しずつ分割する。','必ずHFTに当たる？','必ずではありません。アルゴ執行と高速高頻度戦略は別の分類です。')],sources:[trading,fiea,jpx]},
{number:26,lead:'予測が当たっても、売買コストで利益は減る。IS・VWAP・スプレッドを同じ注文から計算する。',goal:'意思決定価格と約定価格、未約定機会費用を分けて執行結果を測れる。',sections:[
S('直接費用と見えにくい費用','手数料や税等の明示費用に加え、スプレッド、市場インパクト、待機中の価格変動、未約定の機会費用があります。最良気配で買える数量が少ないと平均約定が上がります。銘柄選択の利益と、執行で失う利益を別に測ります。',[['明示費用','手数料等','請求額で見える'],['暗黙費用','スプレッド・価格影響・遅延','基準価格を決めて測る'],['機会費用','未約定による利益逸失等','期間末価格の仮定に依存']],'同じ費用をスプレッドとISに重ねて足さないよう、総費用と内訳の関係を確認します。買いと売りでは符号が逆になり、測定時点でも結果が変わります。執行ベンチマークを事後に都合良く変更しないことが大切です。'),
S('VWAPは出来高で価格を重み付けする','架空市場で1,000円100株、1,010円300株が取引されたらVWAP＝（100,000＋303,000）÷400＝1,007.5円。投資家の買付平均1,008円はVWAPより0.5円高い。ただし市場VWAPと自分の注文条件・時間窓をそろえて比較します。',[['価格×出来高','1,000×100＋1,010×300','403,000円'],['総出来高','400株','同じ計測区間'],['VWAP','1,007.5円','単純平均1,005とは違う']],'VWAPを下回った買付でも、意思決定から市場が大きく上がっていれば全体の取引費用は高い場合があります。逆に市場下落でVWAP超でも意思決定価格より安いことがあります。何の基準に対して良い執行なのかを明示してください。'),
S('ISは紙上と実際の差','買い注文100株、意思決定価格1,000円、80株を1,010で約定、残20未約定、終了価格1,020、手数料100円の例。IS＝80×10＋20×20＋100＝1,300円です。意思決定時に全株買えた仮想結果との差を測ります。',[['約定分の価格差','80×（1,010−1,000）＝800','実際の買付遅れ等'],['未約定機会費用','20×（1,020−1,000）＝400','終了価格で測る仮定'],['総IS','800＋400＋100＝1,300','当初金額10万に対し1.3％']],'終了価格が下落していれば未約定分がマイナス費用となる場合もあります。ISは事業価値を測る指標ではなく、注文の実現との差を測ります。価格変動をすべて執行者の責任とせず、条件と市場の影響も分けて評価します。'),
S('提示と実効スプレッド','買い990・売り1,000なら提示スプレッド10、中値995です。買い約定999なら実効スプレッド＝2×|999−995|＝8円。本講義では直前中値を基準とする絶対値定義を使います。片側コスト4と往復幅8を混同しないでください。',[['提示幅','1,000−990＝10','板の気配差'],['中値','995','直前気配の中央'],['実効幅','2×（999−995）＝8','片側差4の二倍']],'実効スプレッドは将来中値を使う実現スプレッドとも違います。注文量、緊急性、情報、時間窓をそろえて執行を比較します。低手数料でも暗黙費用が高い場合があるため、総コストを見て、速さと価格影響のトレードオフを説明しましょう。')],questions:[Q('VWAP','価格1,000円で100株、1,010円で300株。VWAP＝価格×出来高の合計÷総出来高。','VWAPは？','1,007.5円。'),Q('買いIS','買い100株、決定値1,000円。80株を1,010で約定、20未約定、終了値1,020、費用100円。IS＝80×（1,010−1,000）＋20×（1,020−1,000）＋100。','ISは？','1,300円。'),Q('実効スプレッド','直前買い990・売り1,000、買い約定999（円）。中値＝平均、実効幅＝2×|約定−中値|。','実効幅は？','8円。片側差は4円です。')],sources:[trading,['CFA Institute：A Methodology for Measuring Transaction Costs','https://rpc.cfainstitute.org/research/financial-analysts-journal/1991/a-methodology-for-measuring-transaction-costs'],jpx]},
{number:27,lead:'一社を調べ、CFを作り、一株価値まで計算する。実績・予測・価格を分けた独自の評価演習。',goal:'事業分析、FCFF予測、終価、株主調整、感応度を一つの評価へまとめられる。',sections:[
S('資料と事業の地図から始める','ここでは架空の青葉機器を一社評価します。製品、顧客、地域、競争、売上、原価、設備、運転資本を調べる想定です。実在企業の評価へ進むなら最新の有報、決算、説明会、株式情報をそろえ、同じ期間と範囲のデータを使います。',[['事業','産業機器・継続顧客','架空の事業設定'],['財務','PL・BS・CF・注記','基準・期間・連結を確認'],['評価日','予測開始時点0','実績と予測を分ける']],'企業の主張と自分の推計を分けます。売上増が買収によるものか既存事業か、調整利益が何を除いているかも確認します。最初に評価方法とデータ範囲を決め、結論の株価に合わせて前提を選ばないことが演習の重要なルールです。'),
S('青葉機器のFCFFを作る','年1の仮定売上1,000億円、EBIT率15％、税率30％、償却30、Capex50、NWC増10ならFCFF75。年2もFCFF75とし、年3以降成長0、維持投資が償却に一致・NWC増0でFCFF75が続く簡略モデルを設定します。',[['年1EBIT・NOPAT','150・105','1,000×15％、税30％'],['年1FCFF','105＋30−50−10＝75','億円'],['年2以降CF','75が続く','利益・投資の変化を別仮定']],'年3の投資負担が軽くなるのにCFを75と保つにはNOPATや他の条件が変わります。本例では安定期NOPAT75、償却とCapex同額、NWC増0と明示します。詳細期の営業率を永久化したわけではありません。数値の接続を確認し、説明のない段差を避けましょう。'),
S('事業価値から一株へ移す','WACC10％、年2末終価75/0.10＝750億円。現在価値は75/1.1＋（75＋750）/1.1²＝750。事業外現金50、負債200、他優先請求なしなら株式価値600億円。対象株数一億株で一株600円です。',[['事業価値','750億円','同額永久CFと整合'],['株式価値','750＋50−200＝600','簡略調整'],['一株価値','600億÷1億＝600円','自己株式等調整済み株数']],'市場価格を架空の500円と置けば差100円ですが、DCF前提の正しさを保証しません。事業外現金の範囲、負債時価、潜在株式を確認します。FCFFをWACCで評価したからこそ負債等を出口で調整しているという対応を説明してください。'),
S('感応度と反証条件を提出する','同額永久FCFF75ならWACC12％で事業625、株式475、一株475円。基準の600と比べて125円低い。予測CF60・WACC10％なら事業600、株式450、一株450円。予測と率が変われば、500円を下回る場合もあります。',[['基準','CF75・r10％→600円','現金50・負債200'],['率上昇','CF75・r12％→475円','CF固定感応度'],['CF低下','CF60・r10％→450円','予測シナリオ']],'受注、販売価格、回収日数、設備投資、競合など、どの情報で前提を更新するかを記載します。投資判断の断言ではなく、一枚の評価メモとして資料・仮定・計算・限界をまとめます。数字を自分の言葉で説明して撮影できれば、第3章のモデルを横断した復習になります。')],questions:[Q('FCFF','EBIT150、T30％、償却30、Capex50、NWC増10（億円）。FCFF＝150×0.7＋30−50−10。','FCFFは？','75億円。'),Q('一株価値','永久FCFF75億円、初回一年後、WACC10％、g0。事業価値＝CF/r。現金50・負債200億円、株1億、他調整なし。','一株価値は？','（750＋50−200）億÷1億＝600円。'),Q('率上昇','永久FCFF75億円・WACC12％・g0。事業価値＝75/0.12、現金50・負債200億円、株1億。','一株価値は？','475円。価格500円に対する基準の見方が変わります。')],sources:[fcf,forecast,nyu]},
{number:28,lead:'株主権・情報開示・禁止取引は別のルール。会社法・金融商品取引法・取引所制度を分けて確認する。',goal:'株式投資の基本法規と取引所ルールの役割、インサイダー・相場操縦の注意を説明できる。',sections:[
S('ルールの三層を分ける','会社法は会社の機関、株主権、株式、分配等の基本を定めます。金融商品取引法は開示や取引、業者等を規律し、取引所は上場・売買・適時開示のルールを持ちます。同じ株式でも論点ごとに確認先が違うので、一つの法律に全部を押し込めないでください。',[['会社法','会社・株主・機関・分配','権利の基礎'],['金商法','開示・取引・業者等','投資家保護と市場規律'],['取引所','上場・売買・適時開示','商品・市場に応じた規則']],'法律と自主規制には改定があります。具体的な手続、閾値、期限は対象・行為・時点によるため、この講義では固定数値の丸暗記ではなく確認の地図を作ります。実際の判断は最新条文、公式案内、専門家の確認へ進んでください。'),
S('開示は時点と種類を見る','有価証券報告書等の法定開示、取引所の適時開示、任意IRは役割が違います。決算、増資、買収、業績修正、重要な契約などは、重要性と対象条件に応じて開示が必要です。投資家は公表済み実績と将来見込みを分けて読む必要があります。',[['法定資料','有報等','財務・リスク・事業の体系情報'],['適時開示','重要な会社情報','取引所制度に従う'],['任意資料','説明会・補足','法定情報との整合を確認']],'会社のSNSや噂がすべて法令上の公表要件を満たすとは限りません。更新日と訂正を確認し、古い予想を最新事実として使わないでください。大量保有、公開買付、フェア・ディスクロージャー等は条件があるので、個別の数値は公式制度で確かめます。'),
S('未公表情報と禁止行為','会社関係者等が知った重要な未公表情報に基づく売買は、法令の条件を満たす場合にインサイダー取引規制の対象になります。親族や知人経由なら安全とは限りません。情報伝達・取引推奨にも規制があるので、疑いがあるときは売買を止め管理者へ確認します。',[['情報','重要性・未公表性等','噂と公表を安易に同一視しない'],['人・経路','会社関係者・情報受領等','立場と伝達経路も条件'],['行為','売買・伝達・推奨等','具体的適用は公式確認']],'相場操縦、虚偽表示、見せ玉なども別の禁止行為です。公開情報だけで分析することと、注文で価格を誤認させることは違います。市場効率性の強形仮説は、未公表情報による売買を許す規則ではないという点を確認しましょう。'),
S('実務ではチェックを記録する','売買前に情報の公表、利益相反、保有制限、注文条件、法規を確認し、根拠を記録します。研究記事でも事実・意見・予測を分け、誤りを訂正します。運用者やアナリストの役割は価格分析だけでなく、投資家と市場の信頼を守ることを含みます。',[['事前','情報源・公表・制限確認','不明なら行動を止めて照会'],['執行','注文・数量・価格・監視','法令と社内手順を守る'],['事後','記録・照合・訂正','説明可能性を残す']],'この教材は法律相談ではなく、独自の学習用地図です。実際の適用は契約・主体・制度・時期で変わります。最新のe-Govと取引所案内を確認し、具体的な案件は専門部署や専門家へ相談してください。数字の評価と法令・倫理を両立させて、第3章を締めくくります。')],questions:[Q('確認先','会社法＝株主権・機関・分配、金商法＝開示・取引規律、取引所＝上場・売買ルールという基本分類。','種類株式の権利の基本はどこ？','会社法と会社の定款・発行条件です。'),Q('非公開情報','友人から重要な未公表の買収情報を受けた。情報受領者も法令条件で規制対象になり得る。公表確認できず具体的適用も不明。','友人経由だから即売買してよい？','いいえ。売買を止め、情報の扱いと法令適用を専門部署等へ確認します。'),Q('予測と実績','昨日の公式資料：今期確定利益100、翌期予想120（億円）。予想は保証ではない。','記事で翌期実績120と書ける？','書けません。「翌期予想120」と時点と性質を分けます。')],sources:[law,fiea,jpx,gov]}
];
const fr=['ファーストリテイリング：2026年8月期第3四半期決算サマリー（2026年7月9日）','https://www.fastretailing.com/jp/ir/financial/summary.html'];
equityLectures.find(d=>d.number===6).sections.push(S('企業実例：同じユニクロでも地域を分ける','ファーストリテイリングの2026年8月期第3四半期九カ月累計を見ます。国内ユニクロの売上収益8,676億円・事業利益1,729、海外ユニクロは売上18,340・事業利益3,453です。会社の同じ期間・指標で比較し、三カ月の表と混ぜません。',[['国内ユニクロ','売上8,676・事業利益1,729億','事業利益率約19.93％'],['海外ユニクロ','売上18,340・事業利益3,453億','事業利益率約18.83％'],['海外の範囲','複数地域を合算','一つの国の採算ではない']],'海外という集計だけでどの地域が強いかは分かりません。地域の会社説明や店舗、為替、売上構成を追加して検証します。この二つの事業利益率は公表値からの独自計算で、会社全体の営業利益率やROICとは別です。出所と期間を付けて、ボトムアップの分析へつなげます。'));
equityLectures.find(d=>d.number===6).sources.push(fr);
equityLectures.find(d=>d.number===17).sections.push(S('企業実例：実績から予想を分けて読む','同社の2026年7月9日資料では、九カ月累計の連結売上収益30,651億円・事業利益5,927億円。一方、通期予想は売上39,700・事業利益7,100・営業利益7,300です。2026年9月17日の確認で用いた公表資料であり、架空DCFの入力とは別です。',[['九カ月実績','売上30,651・事業利益5,927','実績事業利益率約19.34％'],['通期予想','売上39,700・事業利益7,100','予想事業利益率約17.88％'],['通期営業利益予想','7,300','事業利益7,100と異なる指標']],'通期予想から九カ月実績を引くと、残り三カ月の売上9,049・事業利益1,173という含意になります。ただし季節性や予想修正があり、これを確定した四半期実績としません。DCFでは同じ利益定義へそろえ、税、投資、運転資本を追加してCFを作る必要があります。'));
equityLectures.find(d=>d.number===17).sources.push(fr);
